  'dodeca.note.icosaStar': "The DICTO-Star with a pyramid on every free face; hollowed, an icosahedron of edge 1 is held exactly by 20 Cleo-Icos on its face centres and 12 flat pentagonal pyramids on its corners (DICTO).",
  'theaetetus.theaetetus.c102': "102 clean pieces",
  'theaetetus.theaetetus.stations': "Stations: every layer closed (215 pieces)",
  'theaetetus.note.theaetetus': "The icosahedron of edge 1 as its 20 Cleo-Icos, the dodecahedron round it as 20 columns (one per face of the icosahedron, its dual partner), then the Spheres of Dharma layers out to the DICTO Hecatodihedron: 102 pieces, none with a dent (DICTO). The Cleo star view grows the same core outward instead: 20 more Cleo-Icos stand on its faces as spikes, their tips are the corners of a dodecahedron (glass), and 12 pentagonal pyramids point in from its faces, and 30 tetrahedra fill the valleys along its edges, 82 pieces in all.",
  'theaetetus.theaetetus.cleostar': "The Cleo star: the core grown outward (82 pieces)",
