  'cy.loop7': "Golden rectangles",
  'cy.note6': "Hypsicles (Euclid's “Book XIV”, c. 150 BC): the icosahedron and the dodecahedron in the same sphere, cut into pyramids from the centre. The icosahedron's 20 are the Cleo-Icos, the dodecahedron's 12 are pentagonal pyramids, and both have the same height: the glass sphere touches every base.",
