  'dj.view.hullRhombo': "菱面体カゴメ網（すべてのピースが 2 つのクラスターに属する）",
  'dj.view.hullOcta': "八面体カゴメ網（ペロブスカイト網）",
  'dj.view.hexa': "DICTO ヘキサのダイヤモンド網（角のジュエルを共有するヘキサ）",
  'dj.view.hexaKey': "DICTO ヘキサとヘキサキーの市松（窓どうし、5 : 3）",
  'dj.prompt.single': "そのセルはクラスターのあいだの、単独の DICTO ジュエル用です。",
  'dj.view.chain': "ジュエルの連鎖（立方体、星形八面体、ドッグスター、正十二面体 ×1/φ³、DICTO ジュエル ×1/φ³）",
  'dj.count': "DICTO ジュエル {even}、星形八面体 {odd}",
  'dj.axes': "5 回軸",
  'dj.prompt.start': "光る DICTO ジュエルをタップして置き、面をタップするとその向こうに次の立体が増えます。",
  'dj.prompt.hole': "その面の向こうは星形八面体です。置くには表示を両方の立体に切り替えてください。",
  'dj.prompt.taken': "そのセルはもう埋まっています。",
  'wiz.4d.z4': 'テッセラクト（4D の立方体）が、すべての整数点にあります。w = 0 での断面は、RD ワールドの単位立方体です。',
  'wiz.4d.d4': '24 胞体（4D の RD）：w = 0 での断面は FCC ワールドです。下部のボタンで 16 胞体を置くモードに切り替わります。',
  'wiz.4d.a4': 'A4 格子の上で頂点を共有する 5 胞体。その Pyrochlore 断面は、Pyrochlore ワールドそのものです。切頂 5 胞体を置くと、その 5 胞体がひとりでに現れます。下部のボタンで二切頂 5 胞体や単独の 5 胞体に切り替わります。',
  'hull.label': 'ハル：',
