  'chains.note.dharma': "正確に満たされた 6 つの殻が φ³ ごとに繰り返す（DICTO #23）。",
  'chains.note.bodhi': "φ² 倍の三十面体の中に 12＋1 個の三十面体、隙間は正確に充填（DICTO #24）。",
  'icosa.fill.off': "すき間を埋める：オフ",
  'icosa.fill.on': "すき間を埋める：オン（Shark Tooth 120 個）",
  'icosa.note.LOTUS_SEED': "辺 φ² の正二十面体を、12 個の正二十面体、小さな 1 個、すき間の部品 AXE・FUJI・CLEO にちょうど分けたもの。表示：113 部品／DICTO 自身の組み方（正十二面体 + J11 12 個 + AXE 30 個 + FUJI 20 個）／中心のまわりの Hasu ユニット 12 個（#19）。",
  'icosa.note.UNITY': "DICTO の 13 セル：二十・十二面体の各五角形に J11。12 個の J11 は 30 個の頂点だけで接します（#19）。",
  'icosa.note.VENUS': "UNITY の 20 のくぼみを VAJRA でふさいだもの（#19）。",
  'icosa.note.STELLA_CORONA': "二十・十二面体、その三角形に正二十面体 20 個、五角形に King of Pentacles 12 個：33 部品が閉じ、接触はすべて面全体。DICTO-Star の正二十面体版の双子（#20）。",
  'icosa.note.KEPLER_STAR_DIADEM': "すべての五芒星に Kepler Star を載せた DICTO Stella-Corona。「すき間を埋める」で細い溝を Shark Tooth 120 個（鏡像 60 組）が閉じます（#20）。",
  'icosa.note.DESHI': "正十二面体の五角形の上に 12 個の正二十面体、中心に小さな正二十面体。30 本の辺を共有。この配置は R. W. Gray（2002）のもの（#19）。",
  'icosa.note.TWELVE_STAR_VOIDS': "二十・十二面体の 20 の三角形それぞれに正二十面体。20 個の殻は Wolfram Demonstration「Cluster of 20 Icosahedra」にあります（#20）。",
  'icosa.note.KEPLER_MACE': "2 つの DICTO Stella-Corona を 1 つの Kepler Star で五回軸に沿ってつないだもの：MACE ネットワークの結合（#20）。",
  'icosa.note.AXE': "すき間の部品：5 辺が 1、1 辺が 1/φ、体積 1/12。2 つの正二十面体が辺のまわりに残すすき間を埋めます。Mosseri–Sadoc タイル t6 の 1/τ 倍（Mosseri & Sadoc 1982）。",
  'icosa.note.FUJI': "すき間の部品：ロータスシードの外側の各頂点にある六角錐。体積 (1 + 3√5)/24。",
  'icosa.note.CLEO': "すき間の部品：ロータスシードの内側の各頂点にある細い四面体。Mosseri–Sadoc タイル t4 の 1/τ 倍（Mosseri & Sadoc 1982）。",
  'icosa.note.TRISKELION': "CLEO と内側の AXE 3 個を 1 つの部品にしたもの。",
  'icosa.note.TRISKELION_HEX': "FUJI と AXE 3 個を 1 つの部品にしたもの。",
  'icosa.note.INNER_EYE': "ロータスシードの外側 12 個の正二十面体が囲む空間：12 のキャップを除いた正十二面体。",
  'icosa.note.HASU': "外側の正二十面体 1 つとそのひれ。これ 12 個と小さな中心でロータスシードになり、1 つずつまっすぐ抜けます。",
  'icosa.note.VAJRA': "UNITY のくぼみを 1 つふさぐ凸の部品。",
  'icosa.note.HMV': "J2 キャップに AXE 5 個と CLEO 5 個：Stella-Corona の五角形のくぼみを埋めるもの。",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) を 1 つの凸の部品にしたもの。",
  'icosa.note.KING_OF_PENTACLES': "HMV に外側の AXE の輪を加え、上面が平らな五芒星になったもの：Stella-Corona の各五角形に 1 つ。",
  'icosa.note.HOUND_TOOTH': "すき間の部品：Mosseri–Sadoc タイル t2 の 1/τ 倍（Mosseri & Sadoc 1982）。五芒星の三角形と小さな二十・十二面体の間にぴったり入ります。",
  'icosa.note.TRICAP': "すき間の部品：Mosseri–Sadoc タイル t3 の 1/τ 倍（Mosseri & Sadoc 1982）。単位三角形の上の平たい角錐。",
  'icosa.note.KEPLER_STAR': "ケプラーの小星型十二面体（1619）の 1/φ 倍から底のとげを除いたもの。King of Pentacles の五芒星に面全体で載ります。",
  'icosa.note.SHARK_TOOTH': "Kepler Star Diadem の 26.06° の溝を埋めるために切った部品（黄金比の部品ではありません）：鏡像の組で 120 個。",
  'icosa.note.BERMUDA_PYRAMID': "小さな正十二面体の横の 63.43° のすき間を埋めるために切った部品（黄金比の部品ではありません）。",
  'wiz.3d.studies': "ユークリッド–ケプラー–パチョーリのセルから厳密に作る立体を 1 つずつ：窓、その変形、引き伸ばした正十二面体。コピーとして、または立体そのものをシアーできます。",
