  'studies.study': "スタディ",
  'studies.windows': "窓：十二面体から6つの星形八面体を除く",
  'studies.windowsStellas': "窓と6つの星形八面体",
  'studies.checker': "窓と星形八面体、市松模様",
  'studies.apart': "離す",
  'studies.note.checker': "星形八面体は窓のもう半分です：偶数のセルに窓、奇数のセルに星形八面体。奇数の立方体はどれも、その星形八面体と、隣り合う6つのセルの削られた屋根とで、隙間も重なりもなく埋まります。体積 12 + 4 = 立方体2つ分。離してかみ合う様子を見てください。",
  'studies.dogstar': "正十二面体とドッグスター",
  'studies.note.dogstar': "偶数のセルに置いた正十二面体（最密な格子充填）は、奇数のセルごとに穴を 1 つ残します。その穴はちょうどドッグスター：大きさ 1/φ³ の十二面体の部分的な星形化（核、12 の角錐すべて、30 のくさびのうち 24、立方体の角を指す 8 本のとげ）で、そのセルの星形八面体の内側にあります。辺は 2/φ⁴、2/φ³、2/φ²、2/φ だけ。十二面体とドッグスターで空間が埋まります。離して見てください。 ドッグスターは George W. Hart による十二面体の星形化 No. 8（1996）で、Hart は正十二面体と交互に並べると空間を埋めることを記しています。Polyhedra-World にも載っています。Hans Walser も、立方体から 6 つの寄棟屋根を取り除いた形（彼の言う「半正十二面体」）として記しており、正十二面体と 3D のチェス盤のように空間を埋めます。",
  'studies.stretch': "引き伸ばした十二面体",
  'studies.slider.stretch': "伸ばし",
  'studies.shear.copies': "シアー：格子上のコピー",
  'studies.shear.solid': "シアー：立体そのもの",
  'studies.expanded': "凸にした窓（外へ押し出し）",
  'studies.push': "押し出し",
  'studies.note.expanded': "各菱形を大きさと角度はそのまま真っすぐ外へ押し出し、凸包をとります。黄金の押し出し（0.727）で立方体の面の上のすき間が平らになり、黄金菱形6枚に：厚い菱形12・黄金菱形6・正三角形8・三角形48。",
  'studies.icosido': "窓から二十・十二面体へ",
  'studies.morph': "変形",
  'studies.note.icosido': "各菱形は大きさと72°の形を保ったまま、法線方向と自分の平面内を滑ります。最後に凸包は二十・十二面体（正五角形12、正三角形20）になり、各菱形は五角形の中にあります。五角形は72°の菱形と黄金三角形でできています。",
  'studies.rdMorph': "窓から菱形十二面体へ",
  'studies.note.rdMorph': "各窓は立方体の辺（長い対角線）を保ち、もう一方の対角線をその周りに回しながら伸ばします。正方形を経て、12枚はぴったり閉じて菱形十二面体になります。その菱形では立方体の辺が短い対角線です。",
  'studies.note.windows': "72°と108°の菱形12枚。どれも十二面体の面の平面上、立方体の辺の上にあります。くり抜かれた部分は三角形48枚。体積はちょうど12。",
  'studies.note.windowsStellas': "72°と108°の菱形12枚。どれも十二面体の面の平面上、立方体の辺の上にあります。くり抜かれた部分は三角形48枚。体積はちょうど12。",
  'studies.note.stretch': "どの伸ばし量でも正五角形8・六角形4・長方形2。辺1本分（1.236）で正方形、2で面で隣り合う2つの凸包。",
  'wiz.3d.targets': "160個の目標セル：すべての辺が等しく、辺が特別な角度でのみ交わる空間充填セル。1つを選んで、単独、面で隣接するセルと一緒、または格子のブロックとして表示します。",
  'wiz.3d.ocdStella': "Ogdoecontahedron のパッキングの一方のネットワークに DICTO OCD Stella、もう一方に正二十面体・正八面体・OCD Stella。",
  'wiz.3d.doubleVision': "Spheres of Dharma とその極反転を同じ空間に：二つのサイクル、そのかみ合わせ、一層ずつ。",
