  'pv.detail.bridges': "3D+ ブリッジ",
  'pv.detail.zomeCredit': "DICTOがZometoolで発見。中サイズの青いストラットだけで組んだ形で、すべての辺がZomeの青い方向に沿っています。",
  'pv.detail.bainCredit': "ベイン変形から：体心立方格子を1つの軸に沿って√2倍に伸ばすと面心立方格子になります。これはその変形で全ての辺が等しくなるセルで、DICTOがKaleidohedraで発見・検証しました。菱形十二面体の形は既知です。正六角形の伸長十二面体（切頂八面体から1つの帯を除いた形）も既知で、DICTOはこの新しい道筋で独立に到達しました。もう1つの伸長十二面体はDICTOの発見です。",
  'pv.detail.regularNineCredit': "Kaleidohedra Regular 9のひとつ：全ての辺が等しく、面が正方形・正六角形・60°のひし形（正三角形2枚）だけでできた、空間を埋める形はこれだけです。DICTOのためのKaleidohedraの二方向探索でちょうど9種が見つかり、これはここに新しく加わった4種のひとつです。",
  'pv.detail.dictoSkewedEdCredit': "KaleidohedraでDICTOの歪んだ菱形十二面体に5番目の辺の方向を加えて発見。Kaleidohedra独自の等辺の伸長十二面体探索と一致したものです。",
  'pv.detail.dogstarCredit': "ドッグスターは George W. Hart による十二面体の星形化 No. 8（1996）で、Hart は正十二面体と交互に並べると空間を埋めることを記しています。Polyhedra-World にも載っています。Hans Walser も、立方体から 6 つの寄棟屋根を取り除いた形（彼の言う「半正十二面体」）として記しており、正十二面体と 3D のチェス盤のように空間を埋めます。DICTO がドッグスターと名付け、面に 6 つのドッグスターをつけた正十二面体をサンスターと呼んでいます。",
  'pv.detail.ekpLink': "DICTO による Euclid–Kepler–Pacioli セルの一部です。層の中に層を重ねて組み上げた姿は次で見られます：",
  'pv.bridge.CUBE': "tesseract {4,3,3} のセルであり断面。24-cell {3,4,3} の頂点図形。",
  'pv.bridge.CUBOCTAHEDRON': "24-cell {3,4,3} のセルを先頭にした影の輪郭。傾けた軸で切ったときの赤道断面。",
  'pv.bridge.D20': "600-cell {3,3,5} の頂点図形。snub 24-cell のセルの一つ。",
  'pv.bridge.D4': "5-cell {3,3,3}、16-cell {3,3,4}、600-cell {3,3,5} のセル。tesseract {4,3,3} と 120-cell {5,3,3} の頂点図形。",
  'pv.bridge.D8': "24-cell {3,4,3} のセル。16-cell {3,3,4} の赤道断面であり、その頂点図形。",
  'pv.bridge.DICTO_SKEWED_RD': "tesseract {4,3,3} の斜めの影。4本の青いストラットの辺の方向は、tesseract の4つの辺の方向を斜めに投影したもの。正則な RD はまっすぐな影です。",
  'pv.bridge.DODECAHEDRON': "120-cell {5,3,3} のセル。",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_OBLATE': "6 次元立方体の 3D の面の影：3D ペンローズ・タイリング（6D 正二十面体準結晶）のタイル。",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_PROLATE': "6 次元立方体の 3D の面の影：3D ペンローズ・タイリング（6D 正二十面体準結晶）のタイル。",
  'pv.bridge.J1_SQUARE_PYRAMID': "菱形の積み上げ（tesseract ＋ 立方体の錐 8 つ ＝ 24-cell {3,4,3}）での立方体の錐のセル。2 つが合わさって 24-cell の正八面体になる。3D では立方体に 6 つ載せると RD になる。",
  'pv.bridge.PENROSE_PRISM_THICK': "太い（72°）ペンローズ菱形（5 次元立方体の正方形の面の影）を辺 1 つ分の高さに立ち上げたもの：層状の 5D 十角形準結晶のタイル。",
