  'wiz.3d.stellaJewel': "DICTO Jewels y stellas octangulas llenan el espacio en damero, o los Jewels solos, cara a cara por sus rombos.",
  'wiz.3d.djTetra': "Cuatro DICTO Jewels en tetraedro, cada par cara con cara, colocados enteros; con stellas octangulas llenan el espacio.",
  'wiz.3d.djOcta': "Seis DICTO Jewels alrededor de una stella octangula, una pieza maciza que arde en su centro; con stellas llenan el espacio.",
  'wiz.3d.djOctet': "Los racimos que comparten Jewels como celdas de la celosía octeto, cada stella dentro de uno octaédrico: una llama eterna azul.",
  'wiz.3d.djKagome': "Racimos tetraédricos que comparten un solo Jewel, al estilo Kagome; los Jewels sueltos entre ellos se rellenan solos, en violeta.",
  'wiz.3d.djHexa': "DICTO Hexas, cada una ocho DICTO Jewels en un cubo, en el patrón del diamante: cada una comparte cuatro Jewels de esquina con sus vecinas, y stellas octangulas llenan todas las celdas entre ellas.",
  'wiz.3d.ssTetra': "Cuatro dodecaedros alrededor de una esquina de celda, colocados enteros; con Dogstars llenan el espacio.",
