  'nets.prompt.cell': "Celda completa: {n} de {total} piezas plegadas. Toca para envolverla capa a capa, de dentro afuera; arrastra el deslizador para desenvolverla.",
  'nets.prompt.cellEmpty': "Aún no hay nada plegado: empieza por los rectángulos de Pacioli; luego cada pieza envuelve a la anterior.",
