  'con.prompt.start': "Toca para llenar la celda naranja: el primer lado del cuadrado, a lo largo de X.",
  'con.prompt.junction': "Unión: {axis} se une a X. Sigue doblando la esquina.",
  'con.prompt.hexagon': "Hexágono: ha surgido de {n} celdas, en tres direcciones. Ahora la estrella de Kagome crece a su alrededor, una arista por toque.",
  'con.prompt.junctionXY': "Unión: XY, X e Y juntas; sigue siendo 2D.",
  'con.prompt.kagome': "Estrella de Kagome: ha surgido de {n} celdas, seis líneas en tres direcciones. A su alrededor, la red de Kagome. Sigue tocando: Z se eleva hacia el pirocloro.",
  'con.prompt.tt': "Tetraedro truncado: el hexágono de Kagome en 3D, el cuerpo: cuatro hexágonos, cuatro triángulos. Ahora sus extremidades: un tetraedro sobre cada triángulo, los cuatro de un toque.",
  'con.prompt.pyrochlore': "Pirocloro: {n} celdas, el tetraedro truncado con un tetraedro sobre cada triángulo: un gran tetraedro, la pieza Pirocloro de 3D+. A su alrededor, la red de pirocloro. Sigue tocando: W se eleva hacia el hiperpirocloro.",
  'con.prompt.t5': "5-celda truncada: el cuerpo en 4D, cinco tetraedros truncados (uno es el tuyo) y cinco tetraedros. Ahora sus extremidades, las cinco de un toque.",
  'con.prompt.hyper': "Hiperpirocloro: {n} celdas, una gran 5-celda, la 5-celda truncada con una pequeña 5-celda sobre cada tetraedro. Toca para girarla a través de W; vuelve a tocar para pararla.",
  'con.prompt.startKagome': "Toca para llenar la celda naranja: el primer lado del hexágono, a lo largo de X.",
  'con.prompt.startRd': "Toca para llenar la celda naranja: el primer lado del rombo, a lo largo de X.",
  'con.prompt.rhombus': "Rombo: la cara propia del RD, {n} celdas, 70,53° y 109,47°. Sigue tocando: Z se eleva hacia el RD, primero su cuerpo.",
  'con.prompt.rdBody': "Cubo: el cuerpo del RD, en su interior; sus aristas son las diagonales cortas de los rombos. Ahora sus extremidades: una pirámide en cada cara, las seis de un toque.",
  'con.prompt.rd': "Dodecaedro rómbico: el cubo con sus seis pirámides, doce rombos, {n} celdas. A su alrededor, los doce RD de su red. Sigue tocando: W separa sus esquinas.",
  'con.prompt.rdTesseract': "Teseracto: el cubo del RD con sus esquinas separadas en W, el cuerpo en 4D. Ahora sus extremidades: los seis vértices se unen a ambos lados de un toque, y otros dos a lo largo de W en otro.",
  'con.prompt.cell24': "24-celda: 96 aristas, la contraparte 4D del RD; su sombra a lo largo de W es el RD. Toca para girarla a través de W; vuelve a tocar para pararla.",
  'con.prompt.cube': "Cubo: ha surgido de {n} celdas. Ahora W, la cuarta dirección, sale de la esquina hacia dentro: sigue tocando para construir un teseracto.",
  'con.prompt.tesseract': "Teseracto: ha surgido de {n} celdas. Toca para girarlo a través de W; vuelve a tocar para pararlo.",
  'con.prompt.square': "Cuadrado: ha surgido de {n} celdas. Ahora Z se eleva desde la esquina: sigue tocando para construir un cubo.",
  'con.prompt.edges': "Ahora cada toque llena una arista restante.",
  'con.prompt.parts': "Ahora cada toque añade una parte entera; las partes iguales llegan juntas.",
