  'dv.note.cycles': "Dos ciclos en un espacio: las Esferas del Dharma (el tuyo) y su inversión polar (invertido), cada sólido una capa transparente. En este ajuste comparten {shared} (oro). Desliza para pasar de un ciclo al otro; en el medio ves los dos.",
