  'vj.view.oh': "El DICTO Hecatogdoecontahedron",
  'vj.note.oh': "El DICTO Hecatogdoecontahedron (artículo #34a): el DICTO Hecatodihedron H (oro) y su polar, el DICTO Ogdoecontahedron O (turquesa), entrelazados en la esfera media del icosaedro truncado; 182 caras y 182 vértices, autodual. Núcleo y envoltura muestran el icosaedro truncado rectificado y unido clásicos; el deslizador separa H y O. Toca un sólido para nombrarlo.",
  'vj.core.on': "Núcleo (rTI): sí",
  'vj.core.off': "Núcleo (rTI): no",
