  'vj.hull.off': "Envoltura (jtI): no",
  'vj.apart': "Separar H y O",
  'vj.film.position': "A lo largo de una vuelta",
  'vj.prompt.start': "Vajrayana: las doce estaciones del ciclo áureo. ▶ las pela una a una, sin fin; ⛶ convierte el corte en vidrio.",
  'vj.prompt.film': "La película: ▶ quita la estación exterior y se acerca a la siguiente, parando en cada una; tras una vuelta el ciclo empieza de nuevo, φ³ menor. ◀ vuelve a construir hacia fuera.",
  'vj.prompt.rtM': "RT → M: una de 30 piezas de un solo tipo, una sobre cada cara del triacontaedro rómbico.",
  'vj.prompt.mI': "M → I·φ³: una de 60 piezas de un solo tipo, una sobre cada cara del DICTO Metaxyhexecontahedron.",
  'vj.prompt.core': "el icosaedro del centro, donde termina la vuelta interior",
  'vj.prompt.cleoLink': "su construcción de 82 piezas está en Theaetetus (Construcción de la Cleo star ↗)",
  'wiz.3d.vajrayana': "El ciclo áureo de doce estaciones: el dodecaedro vuelve como envoltura de la Cleo star y el DICTO Metaxyhexecontahedron cierra el último paso, pelado estación a estación.",
  'dv.xray.wedge': "Corte: se quita la porción del artículo. Toca ⛶ otra vez para un plano que puedes arrastrar.",
  'dv.plane': "Plano",
  'dv.prompt.twin': "El gemelo áureo invierte el anidamiento: φ³ pasa a −1/φ³, así que la vuelta interior saldría mayor que la exterior. Aquí, una estación cada vez.",
  'dv.prompt.twinTap': "Gemelo áureo de {name} (√5 → −√5, caras conservadas).",
  'dv.prompt.toggle.ends': "Extremos compartidos (ρ² = φ²/4): los ciclos comparten el icosaedro y el dodecaedro; 536 piezas por vuelta.",
  'dv.prompt.toggle.middle': "Medio compartido (ρ² = 3φ²/4): los ciclos comparten el icosidodecaedro y el triacontaedro; 502 piezas por vuelta.",
  'dv.film.unwrap': "Desenvolver",
  'dv.film.wrap': "Envolver",
  'dv.film.position': "A lo largo de una vuelta",
  'dv.film.pause': "Pausa",
  'dv.film.twinPos': "Tuyo → gemelo",
  'dv.prompt.film': "La película: Desenvolver pela el sólido capa a capa hacia la vuelta siguiente, sin fin; Envolver la hace volver hacia fuera. Se detiene en cada estación; toca la dirección activa para pausar.",
  'dv.short.cycles': "Dos ciclos en un espacio; compartidos: {shared}. Desliza del tuyo al invertido.",
  'dv.short.interlock': "{n} piezas exactas de {k} tipos por vuelta ({setName}). Toca una pieza para ver su nombre.",
  'dv.short.layer': "Capa {layer} sola: {ln} piezas en este ajuste.",
  'dv.short.twin': "Gemelo áureo de {name}: cada vértice a + b√5 pasa a a − b√5 y se conservan las caras (cada fotograma al mismo tamaño). ▶ recorre la sombra racional (√5 → 0) hasta el gemelo; ◀ vuelve. El gemelo queda al lado.",
  'gbp.prompt.build': "Toca un hexágono para añadir la copia unida ahí, o toca un contorno de ayuda; mantén pulsado para quitar una.",
  'gbp.prompt.buildOff': "Activa Construir para añadir copias.",
  'gbp.prompt.notJoint': "Esa cara no es una unión en esta vista: toca uno de los hexágonos de unión.",
  'gbp.prompt.taken': "Ya hay una copia unida ahí.",
  'gbp.prompt.chorus': "Cinco empaquetamientos se encuentran alrededor de un eje quíntuple; las copias que ceden a lo largo del eje forman la cadena de Fibonacci.",
