  'dodeca.note.star': "Un icosidodecaedro con 12 dodecaedros y 20 J63, cada contacto una cara entera (DICTO #14).",
  'dodeca.note.icosaStar': "El DICTO-Star con una pirámide en cada cara libre; vaciado, un icosaedro de arista 1 queda sujeto exactamente por 20 Cleo-Icos en los centros de sus caras y 12 pirámides pentagonales planas en sus vértices (DICTO).",
  'theaetetus.theaetetus.c102': "102 piezas limpias",
  'theaetetus.theaetetus.stations': "Estaciones: cada capa cerrada (215 piezas)",
  'theaetetus.note.theaetetus': "El icosaedro de arista 1 como sus 20 Cleo-Icos, el dodecaedro a su alrededor como 20 columnas (una por cara del icosaedro, su pareja dual), y luego las capas de Spheres of Dharma hasta el hecatodiedro DICTO: 102 piezas, ninguna con hendidura (DICTO). La vista de la estrella Cleo hace crecer el mismo núcleo hacia fuera: 20 Cleo-Icos más se alzan sobre sus caras como púas, sus puntas son los vértices de un dodecaedro (cristal) y 12 pirámides pentagonales entran desde sus caras, y 30 tetraedros llenan los valles a lo largo de sus aristas: 82 piezas en total.",
