  'chains.note.karma': "El icosaedro y el dodecaedro como capas sin fin uno del otro (DICTO #22).",
  'chains.note.dharma': "Seis capas icosaédricas, cada una llena exactamente, repetidas cada φ³ (DICTO #23).",
  'chains.note.bodhi': "Doce triacontaedros y uno más dentro de uno φ² veces mayor, el hueco lleno exactamente (DICTO #24).",
  'icosa.fill.off': "Rellenar huecos: no",
  'icosa.fill.on': "Rellenar huecos: sí (120 Shark Teeth)",
  'icosa.note.LOTUS_SEED': "Un icosaedro regular de arista φ², cortado exactamente en 12 icosaedros, uno pequeño y las piezas de hueco AXE, FUJI y CLEO. Vistas: 113 piezas; el montaje del propio DICTO, un dodecaedro + 12 J11 + 30 AXE + 20 FUJI; o 12 unidades Hasu alrededor del centro (#19).",
  'icosa.note.UNITY': "La celda de 13 de DICTO: un icosidodecaedro con un J11 en cada pentágono; los 12 J11 se tocan solo en sus 30 vértices (#19).",
  'icosa.note.VENUS': "UNITY con sus 20 hoyuelos cerrados por VAJRA (#19).",
  'icosa.note.STELLA_CORONA': "Un icosidodecaedro, 20 icosaedros en sus triángulos y 12 King of Pentacles en sus pentágonos: 33 piezas, cerrado, todo contacto una cara entera. El gemelo icosaédrico de la DICTO-Star (#20).",
  'icosa.note.KEPLER_STAR_DIADEM': "La DICTO Stella-Corona con una Kepler Star en cada pentagrama. Rellenar huecos añade los 120 Shark Teeth (60 pares especulares) que cierran sus grietas finas (#20).",
  'icosa.note.DESHI': "12 icosaedros sobre los pentágonos de un dodecaedro alrededor de un icosaedro pequeño, compartiendo 30 aristas. La disposición es de R. W. Gray (2002) (#19).",
  'icosa.note.TWELVE_STAR_VOIDS': "Un icosidodecaedro con un icosaedro en cada uno de sus 20 triángulos. La capa de 20 icosaedros es la Wolfram Demonstration \"Cluster of 20 Icosahedra\" (#20).",
  'icosa.note.KEPLER_MACE': "Dos DICTO Stella-Coronas unidas por una Kepler Star a lo largo de un eje quíntuple: el enlace de la red MACE (#20).",
  'icosa.note.AXE': "Pieza de hueco: cinco aristas 1, una arista 1/φ, volumen 1/12. Llena el hueco que dos icosaedros dejan alrededor de una arista. La tesela t6 de Mosseri–Sadoc a escala 1/τ (Mosseri y Sadoc 1982).",
  'icosa.note.FUJI': "Pieza de hueco: una pirámide hexagonal en cada vértice exterior de la Lotus seed, volumen (1 + 3√5)/24.",
  'icosa.note.CLEO': "Pieza de hueco: un tetraedro esbelto en cada vértice interior de la Lotus seed. La tesela t4 de Mosseri–Sadoc a escala 1/τ (Mosseri y Sadoc 1982).",
  'icosa.note.TRISKELION': "CLEO con sus 3 AXE interiores, como una sola pieza.",
  'icosa.note.TRISKELION_HEX': "FUJI con sus 3 AXE, como una sola pieza.",
  'icosa.note.INNER_EYE': "El espacio que encierran los 12 icosaedros exteriores de la Lotus seed: un dodecaedro sin sus 12 casquetes.",
  'icosa.note.HASU': "Un icosaedro exterior con sus aletas: 12 de ellos y el centro pequeño forman la Lotus seed, y cada uno sale en línea recta.",
  'icosa.note.VAJRA': "La pieza convexa que cierra uno de los hoyuelos de UNITY.",
  'icosa.note.HMV': "Un casquete J2 con 5 AXE y 5 CLEO: lo que llena un hoyuelo pentagonal de la Stella-Corona.",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) como una sola pieza convexa.",
  'icosa.note.KING_OF_PENTACLES': "HMV con su anillo exterior de AXE, con un pentagrama plano encima: uno en cada pentágono de la Stella-Corona.",
  'icosa.note.HOUND_TOOTH': "Pieza de hueco: la tesela t2 de Mosseri–Sadoc a escala 1/τ (Mosseri y Sadoc 1982), que encaja entre un triángulo del pentagrama y un icosidodecaedro pequeño.",
  'icosa.note.TRICAP': "Pieza de hueco: la tesela t3 de Mosseri–Sadoc a escala 1/τ (Mosseri y Sadoc 1982), una pirámide plana sobre un triángulo unidad.",
  'icosa.note.KEPLER_STAR': "El pequeño dodecaedro estrellado de Kepler (1619) a escala 1/φ, sin la punta de su base: se apoya en el pentagrama de un King of Pentacles con caras enteras.",
  'icosa.note.SHARK_TOOTH': "La pieza cortada para llenar las grietas de 26,06° de la Kepler Star Diadem (no áurea): 120, en pares especulares.",
  'icosa.note.BERMUDA_PYRAMID': "La pieza cortada para llenar el hueco de 63,43° junto a un dodecaedro pequeño (no áurea).",
  'wiz.3d.studies': "Un sólido cada vez, construido exactamente a partir de la celda de Euclides–Kepler–Pacioli: las ventanas, sus transformaciones y el dodecaedro estirado. Deslízalos como copias o como el sólido mismo.",
  'shear.gap': "Banda roja: aquí la celda ya no llena el espacio (su volumen no es el de la celda de la red). Celda 0 siempre lo hace.",
  'shear.toggle': "Cizalla",
  'shear.toggle.title': "Cizallar la red",
