  'studies.study': "Estudio",
  'studies.windows': "Ventanas: dodecaedro menos seis stellas",
  'studies.windowsStellas': "Ventanas, con las seis stellas",
  'studies.checker': "Ventanas y stellas, en damero",
  'studies.apart': "Separar",
  'studies.note.checker': "La stella octangula es la otra mitad de las ventanas: ventanas en las celdas pares, stellas en las impares, y cada cubo impar es su stella más los tejados tallados de sus seis vecinos, sin huecos ni solapes. Volúmenes 12 + 4 = dos cubos. Sepáralos para ver cómo encajan.",
  'studies.dogstar': "Dodecaedros y sus Dogstars",
  'studies.note.dogstar': "Los dodecaedros regulares en las celdas pares (su empaquetado reticular más denso) dejan un hueco en cada celda impar, y el hueco es exactamente un Dogstar: una estelación parcial de un dodecaedro 1/φ³ de su tamaño (su núcleo, las 12 pirámides, 24 de las 30 cuñas y las 8 puntas que señalan las esquinas del cubo), dentro de la stella octangula de la celda. Sus aristas son solo 2/φ⁴, 2/φ³, 2/φ² y 2/φ. Dodecaedros y Dogstars llenan el espacio; sepáralos para verlo. El Dogstar es la estelación 8 del dodecaedro de George W. Hart (1996), quien señaló que llena el espacio alternado con dodecaedros regulares; también aparece en Polyhedra-World. Hans Walser también lo describe, como un cubo al que se le quitan sus seis tejados a cuatro aguas (su «dodecaedro semirregular»), que llena el espacio con dodecaedros regulares como un tablero de ajedrez en 3D.",
  'studies.stretch': "Dodecaedro estirado",
  'studies.slider.stretch': "Estirar",
  'studies.shear.copies': "Cizalla: copias en la red",
  'studies.shear.solid': "Cizalla: el propio sólido",
  'studies.expanded': "Ventanas convexas (empujadas hacia fuera)",
  'studies.push': "Empuje",
  'studies.note.expanded': "Cada rombo empujado hacia fuera, con el mismo tamaño y ángulo; la envolvente. Con el empuje áureo (0,727) los huecos sobre las caras del cubo se aplanan en 6 rombos áureos: 12 rombos gruesos, 6 rombos áureos, 8 triángulos equiláteros y 48 triángulos.",
  'studies.icosido': "De las ventanas al icosidodecaedro",
  'studies.morph': "Transformar",
  'studies.note.icosido': "Cada rombo se desliza hacia fuera por su normal y a lo largo de su plano, conservando su tamaño y su forma de 72°. Al final su envolvente es el icosidodecaedro (12 pentágonos regulares, 20 triángulos equiláteros): cada rombo queda en un pentágono, que es un rombo de 72° más un triángulo áureo.",
  'studies.rdMorph': "De las ventanas al dodecaedro rómbico",
  'studies.note.rdMorph': "Cada ventana conserva su arista del cubo (su diagonal larga) y gira y estira la otra diagonal a su alrededor, pasando por cuadrados, hasta que las 12 se cierran exactamente como el dodecaedro rómbico, cuyos rombos tienen la arista del cubo como diagonal corta.",
  'studies.note.windows': "12 rombos de 72° y 108°, cada uno en un plano de cara del propio dodecaedro sobre una arista del cubo; el hueco tallado son 48 triángulos. Volumen exactamente 12.",
  'studies.note.windowsStellas': "12 rombos de 72° y 108°, cada uno en un plano de cara del propio dodecaedro sobre una arista del cubo; el hueco tallado son 48 triángulos. Volumen exactamente 12.",
  'studies.note.stretch': "8 pentágonos regulares, 4 hexágonos y 2 rectángulos con cualquier estiramiento; cuadrados con una arista (1,236); la envolvente de dos vecinos de cara con 2.",
  'wiz.3d.targets': "Las 160 celdas objetivo: toda celda que llena el espacio con todas las aristas iguales y cuyas aristas solo se encuentran en ángulos especiales. Elige una para verla sola, con sus vecinas de cara o como un bloque de su red.",
  'wiz.3d.ocdStella': "La DICTO OCD Stella en una red del empaquetamiento del Ogdoecontahedron, con icosaedros, octaedros u otras OCD Stellas en la otra.",
  'wiz.3d.doubleVision': "Las Spheres of Dharma y su inversión polar en un mismo espacio: los dos ciclos, su encaje y una capa cada vez.",
  'wiz.3d.cycles': "Caminos desde un icosaedro hasta sus parientes; cada paso muestra lo que conserva.",
  'wiz.3d.theaetetus': "El núcleo Cleo crecido hasta el DICTO Hecatodihedron, capa a capa.",
  'wiz.3d.chains': "Los tres anidamientos publicados de DICTO: Chain of Karma, Spheres of Dharma y Bodhi Seed.",
  'wiz.3d.octet': "Los tejados de Euclides llevados al icosaedro: cinco redes octeto que crecen con un control deslizante.",
  'wiz.3d.thirteens': "Doce alrededor de uno, de trece maneras. Todos los centros son dorados.",
  'wiz.3d.dodeca': "El DICTO Dodeca-13, la DICTO-Star y la estrella DICTO-ICOSA, montados.",
  'wiz.3d.octetBuild': "El DICTO Icosahedral Octet para construir tú mismo, celda a celda o por grupos.",
  'wiz.3d.breathing': "Tetraedros grandes y pequeños punta con punta, con un control del áureo al pirocloro regular.",
  'wiz.3d.bodhiPyro': "El DICTO Ogdoecontahedron unido por sus hexágonos en redes de pirocloro.",
