  'pv.bridges.section.corners': "Esquinas",
  'pv.detail.bridges': "Puentes 3D+",
  'pv.detail.zomeCredit': "Hallado por DICTO con Zometool, construido con varillas azules medianas: cada arista sigue una de las direcciones azules de Zome.",
  'pv.detail.bainCredit': "Del estiramiento de Bain: estira una red cúbica centrada en el cuerpo √2 veces a lo largo de un eje y se vuelve cúbica centrada en las caras. Son las celdas de ese estiramiento con todas las aristas iguales, halladas y verificadas por DICTO en Kaleidohedra. La forma del dodecaedro rómbico ya se conocía, y también el dodecaedro alargado de hexágonos regulares (el octaedro truncado sin una de sus zonas), al que DICTO llegó de forma independiente por esta nueva vía; el otro dodecaedro alargado lo halló DICTO.",
  'pv.detail.regularNineCredit': "Uno de los Kaleidohedra Regular 9: las únicas formas que llenan el espacio con todas las aristas iguales y caras que son solo cuadrados, hexágonos regulares o rombos de 60° (cada uno dos triángulos equiláteros). La búsqueda en dos sentidos de Kaleidohedra para DICTO halló exactamente nueve; esta es una de las cuatro nuevas aquí.",
  'pv.detail.dictoSkewedEdCredit': "Hallado en Kaleidohedra extendiendo el dodecaedro rómbico sesgado de DICTO con una quinta dirección de arista, coincidente con la propia búsqueda de Kaleidohedra de dodecaedros alargados de arista igual.",
  'pv.detail.dogstarCredit': "El Dogstar es la estelación 8 del dodecaedro de George W. Hart (1996), quien señaló que llena el espacio alternado con dodecaedros regulares; también aparece en Polyhedra-World. Hans Walser también lo describe, como un cubo al que se le quitan sus seis tejados a cuatro aguas (su «dodecaedro semirregular»), que llena el espacio con dodecaedros regulares como un tablero de ajedrez en 3D. DICTO lo llamó Dogstar, y Sunstar a un dodecaedro con 6 Dogstars en sus caras.",
  'pv.detail.ekpLink': "Parte de la celda Euclid–Kepler–Pacioli de DICTO, construida capa dentro de capa, en",
  'pv.bridge.CUBE': "Celda y sección del tesseract {4,3,3}; figura de vértice del 24-cell {3,4,3}.",
  'pv.bridge.CUBOCTAHEDRON': "Contorno de la sombra del 24-cell {3,4,3} vista desde una celda; su sección ecuatorial en un eje inclinado.",
  'pv.bridge.D20': "Figura de vértice del 600-cell {3,3,5}; una celda del snub 24-cell.",
  'pv.bridge.D4': "Celda del 5-cell {3,3,3}, del 16-cell {3,3,4} y del 600-cell {3,3,5}; figura de vértice del tesseract {4,3,3} y del 120-cell {5,3,3}.",
  'pv.bridge.D8': "Celda del 24-cell {3,4,3}; la sección ecuatorial del 16-cell {3,3,4} y su figura de vértice.",
  'pv.bridge.DICTO_SKEWED_RD': "Sombra oblicua del tesseract {4,3,3}: sus cuatro direcciones de arista, de varillas azules, son las cuatro del tesseract proyectadas en diagonal. El RD regular es la sombra de frente.",
  'pv.bridge.DODECAHEDRON': "Celda del 120-cell {5,3,3}.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_OBLATE': "Sombra de una cara 3D del 6-cubo: una pieza de la teselación de Penrose en 3D, el cuasicristal icosaédrico 6D.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_PROLATE': "Sombra de una cara 3D del 6-cubo: una pieza de la teselación de Penrose en 3D, el cuasicristal icosaédrico 6D.",
  'pv.bridge.J1_SQUARE_PYRAMID': "Celda de la pirámide cúbica en el apilamiento rómbico (tesseract + 8 pirámides cúbicas = el 24-cell {3,4,3}): dos se unen en cada uno de sus octaedros. En 3D, seis sobre un cubo forman el RD.",
  'pv.bridge.PENROSE_PRISM_THICK': "El rombo de Penrose grueso (72°), sombra de una cara cuadrada del 5-cubo, elevado una arista: una pieza del cuasicristal decagonal 5D en capas.",
  'pv.bridge.PENROSE_PRISM_THIN': "El rombo de Penrose fino (36°), sombra de una cara cuadrada del 5-cubo, elevado una arista: una pieza del cuasicristal decagonal 5D en capas.",
  'pv.bridge.PYRAMID_TRI_G2': "El tetraedro regular como pirámide de grado 2: celda del 5-cell {3,3,3}, del 16-cell {3,3,4} y del 600-cell {3,3,5}.",
  'pv.bridge.RHOMBIC_DODECAHEDRON': "Sombra (proyección desde un vértice) del tesseract {4,3,3} y del 24-cell {3,4,3}.",
  'pv.bridge.RHOMBIC_ICOSAHEDRON': "Sombra (proyección) del 5-cubo: el zonoedro áureo de cinco ejes.",
  'pv.bridge.RHOMBIC_TRIACONTAHEDRON': "Sombra (proyección) del 6-cubo: el zonoedro áureo de los seis ejes.",
  'pv.bridge.TRUNCATED_OCTAHEDRON': "El permutoedro de orden 4 (sus vértices son las 24 ordenaciones de 1, 2, 3, 4, en una sección 3D del espacio 4D); una celda del omnitruncated 5-cell.",
