  'con.prompt.hexagon': "Hexagone : il a émergé de {n} cellules, dans trois directions. L’étoile de Kagome pousse maintenant autour, une arête par toucher.",
  'con.prompt.junctionXY': "Jonction : XY, X et Y ensemble ; toujours en 2D.",
  'con.prompt.kagome': "Étoile de Kagome : elle a émergé de {n} cellules, six lignes dans trois directions. Autour, le réseau de Kagome. Continuez : Z s’élève vers le pyrochlore.",
  'con.prompt.tt': "Tétraèdre tronqué : l’hexagone de Kagome en 3D, le corps : quatre hexagones, quatre triangles. Maintenant ses membres : un tétraèdre sur chaque triangle, les quatre d’un toucher.",
  'con.prompt.pyrochlore': "Pyrochlore : {n} cellules, le tétraèdre tronqué avec un tétraèdre sur chaque triangle : un grand tétraèdre, la pièce Pyrochlore de la 3D+. Autour, le réseau pyrochlore. Continuez : W s’élève vers l’hyperpyrochlore.",
  'con.prompt.t5': "5-cellule tronquée : le corps en 4D, cinq tétraèdres tronqués (dont le vôtre) et cinq tétraèdres. Maintenant ses membres, les cinq d’un toucher.",
  'con.prompt.hyper': "Hyperpyrochlore : {n} cellules, une grande 5-cellule, la 5-cellule tronquée avec une petite 5-cellule sur chaque tétraèdre. Touchez pour la faire tourner à travers W ; touchez encore pour l’arrêter.",
  'con.prompt.startKagome': "Touchez pour remplir la cellule orange : le premier côté de l’hexagone, le long de X.",
  'con.prompt.startRd': "Touchez pour remplir la cellule orange : le premier côté du losange, le long de X.",
  'con.prompt.rhombus': "Losange : la face propre au RD, {n} cellules, 70,53° et 109,47°. Continuez : Z s’élève vers le RD, son corps d’abord.",
  'con.prompt.rdBody': "Cube : le corps du RD, à l’intérieur ; ses arêtes sont les petites diagonales des losanges. Maintenant ses membres : une pyramide sur chaque face, les six d’un toucher.",
  'con.prompt.rd': "Dodécaèdre rhombique : le cube avec ses six pyramides, douze losanges, {n} cellules. Autour, les douze RD de son réseau. Continuez : W sépare ses coins.",
  'con.prompt.rdTesseract': "Tesseract : le cube du RD, ses coins séparés en W, le corps en 4D. Maintenant ses membres : les six sommets rejoignent les deux côtés d’un toucher, puis deux autres le long de W d’un autre.",
  'con.prompt.cell24': "24-cellule : 96 arêtes, l’équivalent 4D du RD ; son ombre le long de W est le RD. Touchez pour la faire tourner à travers W ; touchez encore pour l’arrêter.",
  'con.prompt.cube': "Cube : il a émergé de {n} cellules. Maintenant W, la quatrième direction, part du coin vers l’intérieur : continuez à toucher pour construire un tesseract.",
  'con.prompt.tesseract': "Tesseract : il a émergé de {n} cellules. Touchez pour le faire tourner à travers W ; touchez encore pour l’arrêter.",
