  'dv.loading': "Chargement des pièces de l’article…",
  'dv.note.cycles': "Deux cycles dans un même espace : les Sphères du Dharma (le vôtre) et leur inversion polaire (inversé), chaque solide une coque transparente. Dans ce réglage, ils partagent {shared} (or). Faites glisser pour passer d’un cycle à l’autre ; au milieu, vous voyez les deux.",
  'dv.note.interlock': "Les deux cycles en un seul solide : chaque couche du vôtre coupée par chaque couche du cycle inversé, {n} pièces convexes exactes de {k} sortes par tour ({setName}), une tranche retirée et le tour suivant au centre. Faites glisser pour recolorer de vos couches aux couches inversées. Touchez une pièce pour la nommer.",
