  'dv.prompt.start': "Dual Vision : les deux cycles de l’article dans un même espace. Extrémités / Milieu déplace la sphère de réciprocité ; touchez une pièce pour la nommer.",
  'vj.loading': "Chargement des douze stations…",
  'vj.note': "Le cycle doré à douze stations, I ⊂ Cleo star ⊂ D′ ⊂ ID ⊂ O ⊂ rTI ⊂ TI ⊂ H ⊂ jtI ⊂ RT ⊂ M ⊂ I·φ³, en coupe ; le tour intérieur se voit au centre. Touchez une couche pour la nommer.",
  'vj.note.pieces': "Les deux dernières étapes remplies : RT → M par 30 pièces d’une seule sorte, M → I·φ³ par 60 d’une seule sorte. Touchez une pièce pour nommer sa couche.",
