  'vj.view.oh': "Le DICTO Hecatogdoecontahedron",
  'vj.note.oh': "Le DICTO Hecatogdoecontahedron (article #34a) : le DICTO Hecatodihedron H (or) et son polaire, le DICTO Ogdoecontahedron O (turquoise), entrelacés dans la sphère médiane de l'icosaèdre tronqué ; 182 faces et 182 sommets, autodual. Noyau et enveloppe montrent l'icosaèdre tronqué rectifié et joint classiques ; le curseur écarte H et O. Touchez un solide pour le nommer.",
