  'vj.prompt.start': "Vajrayana : les douze stations du cycle doré. ▶ les pèle une à une, sans fin ; ⛶ change la coupe en verre.",
  'vj.prompt.film': "Le film : ▶ retire la station extérieure et s’approche de la suivante, en s’arrêtant sur chacune ; après un tour le cycle recommence, φ³ plus petit. ◀ reconstruit vers l’extérieur.",
  'vj.prompt.rtM': "RT → M : une des 30 pièces d’une seule sorte, une sur chaque face du triacontaèdre rhombique.",
