  'vj.prompt.core': "l’icosaèdre au centre, où finit le tour intérieur",
  'vj.prompt.cleoLink': "sa construction en 82 pièces est dans Theaetetus (Construction de la Cleo star ↗)",
  'wiz.3d.vajrayana': "Le cycle doré à douze stations : le dodécaèdre revient comme enveloppe de la Cleo star, le DICTO Metaxyhexecontahedron ferme la dernière étape, pelé station par station.",
  'dv.xray.wedge': "Coupe : la part de l’article est retirée. Touchez ⛶ encore pour un plan à faire glisser.",
  'dv.plane': "Plan",
  'dv.prompt.twin': "Le jumeau doré retourne l’emboîtement : φ³ devient −1/φ³, le tour intérieur deviendrait plus grand que l’extérieur. Ici, une station à la fois.",
  'dv.prompt.twinTap': "Jumeau doré de {name} (√5 → −√5, faces gardées).",
  'dv.prompt.toggle.ends': "Extrémités partagées (ρ² = φ²/4) : les cycles partagent l’icosaèdre et le dodécaèdre ; 536 pièces par tour.",
  'dv.prompt.toggle.middle': "Milieu partagé (ρ² = 3φ²/4) : les cycles partagent l’icosidodécaèdre et le triacontaèdre ; 502 pièces par tour.",
