  'dv.prompt.film': "Le film : Déballer épluche le solide couche par couche jusqu’au tour suivant, sans fin ; Emballer le fait revenir vers l’extérieur. Il marque une pause à chaque station ; touchez le sens en cours pour mettre en pause.",
  'dv.short.cycles': "Deux cycles dans un même espace ; partagés : {shared}. Glissez du vôtre au cycle inversé.",
