  'dv.short.twin': "Jumeau doré de {name} : chaque sommet a + b√5 devient a − b√5, chaque face est gardée (chaque image à la même taille). ▶ passe par l’ombre rationnelle (√5 → 0) jusqu’au jumeau ; ◀ revient. Le jumeau est à côté.",
