  'dodeca.note.star': "Un icosidodécaèdre avec 12 dodécaèdres et 20 J63, chaque contact une face entière (DICTO #14).",
  'dodeca.note.icosaStar': "Le DICTO-Star avec une pyramide sur chaque face libre ; évidé, un icosaèdre d’arête 1 est tenu exactement par 20 Cleo-Icos au centre de ses faces et 12 pyramides pentagonales plates sur ses sommets (DICTO).",
  'theaetetus.theaetetus.c102': "102 pièces nettes",
  'theaetetus.theaetetus.stations': "Étapes : chaque couche fermée (215 pièces)",
  'theaetetus.note.theaetetus': "L’icosaèdre d’arête 1 en ses 20 Cleo-Icos, le dodécaèdre autour en 20 colonnes (une par face de l’icosaèdre, son partenaire dual), puis les couches de Spheres of Dharma jusqu’à l’hécatodièdre DICTO : 102 pièces, aucune creusée (DICTO). La vue de l’étoile Cleo fait croître le même cœur vers l’extérieur : 20 Cleo-Icos de plus se dressent sur ses faces en pointes, dont les sommets sont ceux d’un dodécaèdre (verre), et 12 pyramides pentagonales entrent depuis ses faces, et 30 tétraèdres comblent les vallées le long de ses arêtes : 82 pièces en tout.",
