  'cy.loop5': "Chemin Admiral Cap",
  'cy.note5': "L'icosaèdre + 6 Admiral Caps = l'octaèdre. Chaque coiffe repose sur un petit côté d'un rectangle d'or de Pacioli, sa pointe sur l'axe de ce côté ; affichez les rectangles pour le voir.",
  'cy.keep.admiral': "6 Admiral Caps sur les petits côtés des rectangles",
  'cy.loop6': "Hypsiclès",
  'cy.loop7': "Rectangles d'or",
  'cy.note6': "Hypsiclès (le « Livre XIV » d'Euclide, v. 150 av. J.-C.) : l'icosaèdre et le dodécaèdre dans la même sphère, découpés en pyramides depuis le centre. Les 20 de l'icosaèdre sont les Cleo-Icos, les 12 du dodécaèdre sont des pyramides pentagonales, et toutes ont la même hauteur : la sphère de verre touche chaque base.",
  'cy.note7': "Les trois rectangles d'or de Pacioli (côtés 1 : φ) se croisent à angle droit. Leurs 12 coins sont les sommets de l'icosaèdre ; les faces se remplissent entre eux.",
