  'chains.bodhi.hollow': "Le creux : 60 Vajras",
  'chains.note.karma': "L’icosaèdre et le dodécaèdre, coques sans fin l’un de l’autre (DICTO #22).",
  'chains.note.dharma': "Six coques icosaédriques remplies exactement, répétées tous les φ³ (DICTO #23).",
  'chains.note.bodhi': "Douze triacontaèdres et un de plus dans un triacontaèdre φ² fois plus grand, le vide rempli exactement (DICTO #24).",
  'icosa.fill.off': "Combler les vides : non",
  'icosa.fill.on': "Combler les vides : oui (120 Shark Teeth)",
  'icosa.note.LOTUS_SEED': "Un icosaèdre régulier d'arête φ², découpé exactement en 12 icosaèdres, un petit et les pièces de vide AXE, FUJI et CLEO. Vues : 113 pièces ; le montage de DICTO lui-même, un dodécaèdre + 12 J11 + 30 AXE + 20 FUJI ; ou 12 unités Hasu autour du centre (#19).",
  'icosa.note.UNITY': "La cellule à 13 de DICTO : un icosidodécaèdre avec un J11 sur chaque pentagone ; les 12 J11 ne se touchent qu'en ses 30 sommets (#19).",
  'icosa.note.VENUS': "UNITY avec ses 20 creux fermés par VAJRA (#19).",
  'icosa.note.STELLA_CORONA': "Un icosidodécaèdre, 20 icosaèdres sur ses triangles et 12 King of Pentacles sur ses pentagones : 33 pièces, fermé, chaque contact une face entière. Le jumeau icosaédrique de la DICTO-Star (#20).",
  'icosa.note.KEPLER_STAR_DIADEM': "La DICTO Stella-Corona avec une Kepler Star sur chaque pentagramme. Combler les vides ajoute les 120 Shark Teeth (60 paires miroir) qui ferment ses fentes étroites (#20).",
  'icosa.note.DESHI': "12 icosaèdres sur les pentagones d'un dodécaèdre autour d'un petit icosaèdre, partageant 30 arêtes. La disposition est celle de R. W. Gray (2002) (#19).",
  'icosa.note.TWELVE_STAR_VOIDS': "Un icosidodécaèdre avec un icosaèdre sur chacun de ses 20 triangles. La couche de 20 icosaèdres est la Wolfram Demonstration « Cluster of 20 Icosahedra » (#20).",
  'icosa.note.KEPLER_MACE': "Deux DICTO Stella-Coronas reliées par une Kepler Star le long d'un axe d'ordre cinq : le lien du réseau MACE (#20).",
  'icosa.note.AXE': "Pièce de vide : cinq arêtes 1, une arête 1/φ, volume 1/12. Elle comble le vide que deux icosaèdres laissent autour d'une arête. La tuile t6 de Mosseri–Sadoc à l'échelle 1/τ (Mosseri et Sadoc 1982).",
  'icosa.note.FUJI': "Pièce de vide : une pyramide hexagonale à chaque sommet extérieur de la Lotus seed, volume (1 + 3√5)/24.",
  'icosa.note.CLEO': "Pièce de vide : un tétraèdre élancé à chaque sommet intérieur de la Lotus seed. La tuile t4 de Mosseri–Sadoc à l'échelle 1/τ (Mosseri et Sadoc 1982).",
  'icosa.note.TRISKELION': "CLEO avec ses 3 AXE intérieures, en une seule pièce.",
  'icosa.note.TRISKELION_HEX': "FUJI avec ses 3 AXE, en une seule pièce.",
  'icosa.note.INNER_EYE': "L'espace que renferment les 12 icosaèdres extérieurs de la Lotus seed : un dodécaèdre moins ses 12 calottes.",
  'icosa.note.HASU': "Un icosaèdre extérieur avec ses ailettes : 12 d'entre eux et le petit centre forment la Lotus seed, chacun se retirant tout droit.",
  'icosa.note.VAJRA': "La pièce convexe qui ferme un des creux d'UNITY.",
  'icosa.note.HMV': "Une calotte J2 avec 5 AXE et 5 CLEO : ce qui remplit un creux pentagonal de la Stella-Corona.",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) en une seule pièce convexe.",
  'icosa.note.KING_OF_PENTACLES': "HMV avec son anneau extérieur d'AXE, un pentagramme plat au sommet : un sur chaque pentagone de la Stella-Corona.",
  'icosa.note.HOUND_TOOTH': "Pièce de vide : la tuile t2 de Mosseri–Sadoc à l'échelle 1/τ (Mosseri et Sadoc 1982), qui se loge entre un triangle du pentagramme et un petit icosidodécaèdre.",
  'icosa.note.TRICAP': "Pièce de vide : la tuile t3 de Mosseri–Sadoc à l'échelle 1/τ (Mosseri et Sadoc 1982), une pyramide plate sur un triangle unité.",
  'icosa.note.KEPLER_STAR': "Le petit dodécaèdre étoilé de Kepler (1619) à l'échelle 1/φ, sans la pointe de sa base : il repose sur le pentagramme d'un King of Pentacles par des faces entières.",
  'icosa.note.SHARK_TOOTH': "La pièce taillée pour combler les fentes de 26,06° de la Kepler Star Diadem (non dorée) : 120, par paires miroir.",
  'icosa.note.BERMUDA_PYRAMID': "La pièce taillée pour combler le vide de 63,43° à côté d'un petit dodécaèdre (non dorée).",
  'wiz.3d.studies': "Un solide à la fois, construit exactement à partir de la cellule d'Euclide–Kepler–Pacioli : les fenêtres, leurs transformations et le dodécaèdre étiré. Cisaillez-les en copies ou en solide.",
