  'dj.view.hullRd': "마름모십이면체 카고메 망",
  'dj.view.hullCube': "정육면체 카고메 망",
  'dj.view.hullCuboSolid': "정육팔면체 카고메 망 (속이 찬)",
  'dj.view.hullCuboHollow': "정육팔면체 카고메 망 (속이 빈)",
  'dj.view.hullRhombo': "마름모육면체 카고메 망 (모든 조각이 두 클러스터에)",
  'dj.view.hullOcta': "팔면체 카고메 망 (페로브스카이트 망)",
  'dj.view.hexa': "DICTO 헥사 다이아몬드 망 (모서리 주얼을 공유하는 헥사)",
  'dj.view.hexaKey': "DICTO 헥사와 헥사키 바둑판 (창끼리, 5 : 3)",
  'dj.prompt.single': "그 셀은 클러스터 사이의 DICTO 주얼 하나를 위한 자리입니다.",
  'dj.view.chain': "주얼 연쇄 (정육면체, 별 팔면체, 도그스타, 정십이면체 ×1/φ³, DICTO 주얼 ×1/φ³)",
  'dj.count': "DICTO 주얼 {even}개, 스텔라 옥탕굴라 {odd}개",
  'dj.axes': "5회 축",
  'dj.prompt.start': "빛나는 DICTO 주얼을 탭해 놓고, 면을 탭하면 그 너머에 조각이 더해집니다.",
  'dj.prompt.hole': "그 면 너머는 스텔라 옥탕굴라 자리입니다. 놓으려면 보기를 두 조각 모두로 바꾸세요.",
  'dj.prompt.taken': "그 셀은 이미 채워져 있습니다.",
  'wiz.4d.z4': '테서랙트(4D 정육면체)가 모든 정수 좌표점에 있습니다. w = 0에서의 단면은 RD 월드의 단위 정육면체입니다.',
  'wiz.4d.d4': '24포체(4D의 RD): w = 0에서의 단면은 FCC 월드입니다. 아래쪽 버튼으로 16포체를 놓도록 바꿀 수 있습니다.',
  'wiz.4d.a4': 'A4 격자 위에서 꼭짓점을 공유하는 5포체. 그 Pyrochlore 단면이 바로 Pyrochlore 월드입니다. 깎은 5포체를 놓으면 그 5포체가 저절로 나타납니다. 아래쪽 버튼으로 두 번 깎은 5포체나 단독 5포체로 바꿀 수 있습니다.',
  'hull.label': '껍질 모양:',
  'hull.steps': '단계(육팔면체)',
