  'hull.info.shells': '층',
  'hull.info.complete': '{n}층 완성',
  'hull.info.shellRow': '{n}층: {total}개 중 {have}개',
  'hull.info.none': '조각을 놓아 시작하세요',
  'hull.prompt.added.one': '{shell}층: 조각 {n}개를 더했습니다.',
  'hull.prompt.added.other': '{shell}층: 조각 {n}개를 더했습니다.',
