  'hull.prompt.limit': '그 층을 더하면 조각이 {max}개를 넘습니다.',
  'hull.prompt.hull': '껍질 모양: {name}. 이제 색 띠가 이 모양으로 바깥쪽으로 세어집니다.',
  'wiz.3d.shells': 'RD 층으로 껍질을 쌓습니다. 층마다 색 띠가 있으며, 첫 조각에서부터 육팔면체, 구, 또는 고른 모양으로 바깥쪽으로 셉니다.',
