  'wiz.1d.constructKagome': "1차원 칸으로 육각형을 만들고, 그 둘레에 카고메 별(세 방향의 여섯 선), 그리고 격자로.",
  'wiz.1d.constructRd': "1차원 칸으로 RD 자신의 마름모를 만들고, 마름모 십이면체로: 먼저 안쪽의 정육면체, 그다음 여섯 피라미드. 그리고 격자로.",
  'con.open': "{dim}에서 열기",
  'wiz.2d.nets': "입체의 유령 전개도를 면마다 따라간 뒤 접어서 입체로 만드세요.",
