  'nets.prompt.faces': "이제 한 번 탭할 때마다 전개도의 다음 면이 만들어집니다.",
  'nets.prompt.done': "{name}: 전개도가 완성되었습니다. 탭해서 접거나 슬라이더를 드래그하세요.",
  'nets.prompt.folded': "{name}: 전개도에서 접혀 만들어졌습니다. 슬라이더로 펼칠 수 있습니다.",
  'nets.fold': "접기: 평평함에서 닫힘까지",
  'pack.spheres': "Spherical: 모든 조각을 구로 표시합니다. 온전한 RD는 이웃 열둘과 닿습니다. 슬라이더로 크기를 바꿉니다. 보기만 바뀌며 셀은 그대로입니다.",
  'pack.spheres@polyhedraverse': "Spherical: 모든 도형을 같은 부피의 구(도형 안쪽)로 표시합니다. 슬라이더로 크기를 바꿉니다. 보기일 뿐이며 도형은 그대로입니다.",
  'pack.voids': "빈틈: 채워진 구가 남기는 공간, 팔면체 빈틈(금색, 둘레에 구 여섯)과 사면체 빈틈(장밋빛, 둘레에 구 넷). 완전히 둘러싸인 곳만 보여 줍니다.",
  'pack.off': "Spherical: 끔.",
  'pack.radius': "구 크기",
  'pack.none': "온전한 RD를 몇 개 놓으면 그 사이의 빈틈을 볼 수 있습니다.",
  'nets.group.voronoi': "보로노이 셀",
