  'gbp.size.chorus': "반지름: {n}",
  'gbp.note.network': "네트워크 하나: 복사본 {n}개, 각각 육각형 네 개로 접합. 접합부(빨강)는 꼭짓점을 공유하는 사면체(분홍)의 파이로클로어 격자 위에 있습니다.",
  'gbp.note.double': "틈에 두 번째 네트워크를 넣으면 체심입방 채움이 되어 공간의 77.43%를 차지합니다(복사본 {n}개). 나머지는 복사본마다 틈 조각 72개가 정확히 채웁니다.",
  'gbp.holes.on': "빈틈: Bull-horns OG adaptor",
  'gbp.holes.off': "빈틈: 작은 조각 72개",
  'gbp.note.holes': "이중 네트워크를 둘러싼 레진을 OG 6개 사이의 구멍마다 자른다: 한 가지 조각, DICTO의 Bull-horns OG adaptor, 복사본마다 3개. OG가 공간의 77.4332%, 어댑터가 22.5668%, 정확하며 남는 곳이 없다 ({n}개).",
  'gbp.note.voice': "목소리 {v} (5개 중): 내접 정육면체 하나의 채움(복사본 {n}개).",
  'gbp.note.chorus': "다섯 목소리가 5회 대칭축 둘레에 모입니다. 반지름 10까지 정확: {k}개 유지, {g}개 제거. 빨간 점: 피보나치 척추(DICTO #30).",
  'gbp.prompt.start': "DICTO 오그도에콘타헤드론을 육각형 면끼리 접합합니다. 아래에서 보기를 고르고, 만들기로 복사본을 더할 수 있습니다.",
  'dv.loading': "논문의 조각을 불러오는 중…",
  'dv.note.cycles': "한 공간의 두 순환: 다르마의 구(당신의 순환)와 그 극 반전(뒤집힌 순환). 각 입체는 비치는 껍질이다. 이 설정에서 둘은 {shared}(금색)을 공유한다. 슬라이더로 한 순환에서 다른 순환으로 넘어가고, 가운데에서는 둘 다 보인다.",
  'dv.note.interlock': "두 순환을 하나의 입체로: 당신의 각 층을 뒤집힌 순환의 각 층으로 잘라, 한 바퀴에 {k}종 {n}개의 정확한 볼록 조각({setName}). 한 조각을 잘라 내고 가운데에 다음 바퀴를 둔다. 슬라이더로 색을 당신의 층에서 뒤집힌 층으로 바꾼다. 조각을 누르면 이름이 나온다.",
  'dv.note.layer': "원래 층 {layer}만: 이 설정에서 {ln}개의 조각. 조각을 누르면 이름이 나온다.",
