  'os.prompt.swap.ico': "두 번째 네트워크에 정이십면체: 같은 결정 (Fd-3), 모든 입체가 면으로 맞닿는다.",
  'os.prompt.swap.octa': "두 번째 네트워크에 정팔면체: 같은 결정 (Fd-3). 꼭짓점이 OCD 스텔라에 들어간다.",
  'os.prompt.swap.alone': "두 네트워크 모두 OCD 스텔라: OCD 스텔라의 단순 bcc 채움.",
  'os.prompt.stella': "DICTO OCD 스텔라: 꼭짓점 48, 면 50. 채움 셀의 87.12%를 채운다 (정확).",
  'os.prompt.notched': "홈이 파인 DICTO OCD 스텔라: 정팔면체 꼭짓점 6개가 들어간다 (부피의 8.0%).",
  'os.prompt.ico': "옥도에콘타헤드론의 육각형 면 20개가 만드는 정이십면체. 8면이 접합면에 닿는다.",
