  'os.prompt.gap0': "빈틈 조각: 정이십면체 쐐기, 이십면체마다 {n}개 (꼭짓점 6, 면 5).",
  'os.prompt.gap1': "빈틈 조각: OCD 스텔라 삼각형 위의 덮개, OCD 스텔라마다 {n}개 (꼭짓점 9, 면 7).",
  'os.prompt.gap2': "빈틈 조각: OCD 스텔라 황금 육각형 위의 판, OCD 스텔라마다 {n}개 (꼭짓점 16, 면 12).",
  'os.prompt.gap3': "빈틈 조각: OCD 스텔라 황금 사각형 위의 얇은 쐐기, OCD 스텔라마다 {n}개 (꼭짓점 6, 면 5).",
