  'dv.prompt.start': "Dual Vision: 논문의 두 순환을 한 공간에. 양 끝 / 가운데 공유가 반전의 구를 옮긴다. 조각을 누르면 이름이 나온다.",
  'vj.loading': "열두 단계를 불러오는 중…",
  'vj.note': "열두 단계의 황금 순환 I ⊂ Cleo star ⊂ D′ ⊂ ID ⊂ O ⊂ rTI ⊂ TI ⊂ H ⊂ jtI ⊂ RT ⊂ M ⊂ I·φ³ 의 절개도. 안쪽 순환이 들여다보인다. 껍질을 누르면 이름이 나온다.",
  'vj.note.pieces': "마지막 두 단계를 채움: RT → M 은 한 종류 30개, M → I·φ³ 는 한 종류 60개. 조각을 누르면 층 이름이 나온다.",
  'vj.pieces.on': "조각: 켬",
