  'vj.cleo': "Cleo star 조립 ↗",
  'vj.view.cycle': "열두 단계 순환",
  'vj.view.oh': "DICTO Hecatogdoecontahedron",
  'vj.note.oh': "DICTO Hecatogdoecontahedron (논문 #34a): DICTO Hecatodihedron H(금색)와 그 극쌍대 DICTO Ogdoecontahedron O(청록)가 깎은 정이십면체의 중구에서 맞물린다. 182 면, 182 꼭짓점, 자기쌍대. 코어와 외피 스위치는 고전적인 rectified·joined truncated icosahedron 을 보여 준다. 슬라이더로 H 와 O 를 떼어 놓는다. 입체를 탭하면 이름이 나온다.",
  'vj.core.on': "코어 (rTI): 켜짐",
  'vj.core.off': "코어 (rTI): 꺼짐",
