  'vj.hull.off': "외피 (jtI): 꺼짐",
  'vj.apart': "H 와 O 떼어 놓기",
  'vj.film.position': "한 바퀴 안의 위치",
  'vj.prompt.start': "Vajrayana: 황금 순환의 열두 단계. ▶ 로 한 단계씩 끝없이 벗긴다. ⛶ 는 절개도를 유리로 바꾼다.",
  'vj.prompt.film': "필름: ▶ 는 바깥 단계를 벗기고 다음으로 다가가며 단계마다 멈춘다. 한 바퀴가 끝나면 φ³ 작게 순환이 다시 시작된다. ◀ 는 바깥으로 다시 쌓는다.",
  'vj.prompt.rtM': "RT → M: 한 종류 30개 중 하나. 마름모 삼십면체의 면마다 하나.",
  'vj.prompt.mI': "M → I·φ³: 한 종류 60개 중 하나. DICTO Metaxyhexecontahedron 의 면마다 하나.",
  'vj.prompt.core': "중심의 정이십면체, 안쪽 순환이 끝나는 곳",
  'vj.prompt.cleoLink': "82조각 조립은 Theaetetus 에 (Cleo star 조립 ↗)",
  'wiz.3d.vajrayana': "열두 단계의 황금 순환: Cleo star 의 외피로 돌아온 정십이면체, 마지막 단계를 닫는 DICTO Metaxyhexecontahedron, 한 단계씩 벗겨 본다.",
  'dv.xray.wedge': "절개: 논문의 조각을 뺐다. ⛶을 한 번 더 누르면 끌 수 있는 평면.",
  'dv.plane': "평면",
  'dv.prompt.twin': "황금 쌍둥이는 겹침을 뒤집는다: φ³은 −1/φ³이 되어 안쪽 순환이 바깥보다 커진다. 여기서는 한 번에 한 단계.",
  'dv.prompt.twinTap': "{name}의 황금 쌍둥이 (√5 → −√5, 면 유지).",
  'dv.prompt.toggle.ends': "양 끝 공유 (ρ² = φ²/4): 정이십면체와 정십이면체를 공유. 한 바퀴에 536개.",
  'dv.prompt.toggle.middle': "가운데 공유 (ρ² = 3φ²/4): 십이·이십면체와 마름모 삼십면체를 공유. 한 바퀴에 502개.",
