  'dv.film.pause': "일시 정지",
  'dv.film.twinPos': "당신의 것 → 쌍둥이",
  'dv.prompt.film': "필름: 풀기는 입체를 층마다 벗겨 다음 바퀴로 끝없이 나아가고, 감싸기는 바깥으로 되돌린다. 정거장마다 멈추며, 진행 중인 방향을 다시 누르면 일시정지한다.",
  'dv.short.cycles': "한 공간의 두 순환. 공유: {shared}. 슬라이더로 뒤집힌 순환으로.",
