  'theaetetus.note.theaetetus': "모서리 1의 이십면체를 Cleo-Ico 20개로, 그 둘레의 십이면체를 기둥 20개(이십면체 면마다 하나, 쌍대 짝)로 나누고, 이어 Spheres of Dharma 층이 DICTO 헤카토다이헤드론까지: 오목한 곳 없는 102조각 (DICTO). Cleo 별 보기는 같은 핵을 바깥으로 키운다: 면 위에 Cleo-Ico 20개를 가시로 더 세우면 그 끝이 십이면체(유리)의 꼭짓점이 되고, 그 면에서 오각뿔 12개가 안쪽으로 들어온다. 그리고 모서리를 따라 난 골짜기를 사면체 30개가 채워 모두 82조각이 된다.",
