  'icosa.note.UNITY': "DICTO의 13셀: 십이·이십면체의 각 오각형에 J11. 12개의 J11은 30개의 꼭짓점에서만 닿습니다 (#19).",
  'icosa.note.VENUS': "UNITY의 20개 오목한 곳을 VAJRA로 막은 것 (#19).",
  'icosa.note.STELLA_CORONA': "십이·이십면체, 그 삼각형에 정이십면체 20개, 오각형에 King of Pentacles 12개: 조각 33개가 닫히고 모든 접촉이 면 전체. DICTO-Star의 정이십면체 쌍둥이 (#20).",
  'icosa.note.KEPLER_STAR_DIADEM': "모든 오각별에 Kepler Star를 올린 DICTO Stella-Corona. 틈 채우기는 가는 틈을 막는 Shark Tooth 120개(거울상 60쌍)를 더합니다 (#20).",
  'icosa.note.DESHI': "정십이면체의 오각형 위 정이십면체 12개, 가운데 작은 정이십면체, 모서리 30개를 공유. 이 배치는 R. W. Gray(2002)의 것 (#19).",
  'icosa.note.TWELVE_STAR_VOIDS': "십이·이십면체의 20개 삼각형마다 정이십면체. 정이십면체 20개의 껍질은 Wolfram Demonstration \"Cluster of 20 Icosahedra\" (#20).",
  'icosa.note.KEPLER_MACE': "두 DICTO Stella-Corona를 Kepler Star 하나로 오중 축을 따라 이은 것: MACE 네트워크의 결합 (#20).",
  'icosa.note.AXE': "틈 조각: 모서리 다섯 개가 1, 하나가 1/φ, 부피 1/12. 두 정이십면체가 모서리 둘레에 남기는 틈을 채웁니다. Mosseri–Sadoc 타일 t6의 1/τ배 (Mosseri & Sadoc 1982).",
  'icosa.note.FUJI': "틈 조각: Lotus seed의 바깥 꼭짓점마다 있는 육각뿔, 부피 (1 + 3√5)/24.",
  'icosa.note.CLEO': "틈 조각: Lotus seed의 안쪽 꼭짓점마다 있는 가는 사면체. Mosseri–Sadoc 타일 t4의 1/τ배 (Mosseri & Sadoc 1982).",
  'icosa.note.TRISKELION': "CLEO와 안쪽 AXE 3개를 한 조각으로.",
  'icosa.note.TRISKELION_HEX': "FUJI와 AXE 3개를 한 조각으로.",
  'icosa.note.INNER_EYE': "Lotus seed의 바깥 정이십면체 12개가 둘러싼 공간: 뚜껑 12개를 뺀 정십이면체.",
  'icosa.note.HASU': "바깥 정이십면체 하나와 그 지느러미: 이것 12개와 작은 중심이 Lotus seed가 되고, 하나씩 곧게 빠집니다.",
  'icosa.note.VAJRA': "UNITY의 오목한 곳 하나를 막는 볼록 조각.",
  'icosa.note.HMV': "J2 뚜껑에 AXE 5개와 CLEO 5개: Stella-Corona의 오각형 오목한 곳을 채우는 것.",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone)를 하나의 볼록 조각으로.",
  'icosa.note.KING_OF_PENTACLES': "HMV에 바깥 AXE 고리를 더해 윗면이 평평한 오각별: Stella-Corona의 오각형마다 하나.",
  'icosa.note.HOUND_TOOTH': "틈 조각: Mosseri–Sadoc 타일 t2의 1/τ배 (Mosseri & Sadoc 1982), 오각별의 삼각형과 작은 십이·이십면체 사이에 꼭 맞습니다.",
  'icosa.note.TRICAP': "틈 조각: Mosseri–Sadoc 타일 t3의 1/τ배 (Mosseri & Sadoc 1982), 단위 삼각형 위의 납작한 뿔.",
  'icosa.note.KEPLER_STAR': "케플러의 작은 별모양 십이면체(1619)의 1/φ배에서 밑면의 가시를 뺀 것: King of Pentacles의 오각별 위에 면 전체로 놓입니다.",
  'icosa.note.SHARK_TOOTH': "Kepler Star Diadem의 26.06° 틈을 채우려고 자른 조각(황금비 조각이 아님): 거울상 쌍으로 120개.",
  'icosa.note.BERMUDA_PYRAMID': "작은 정십이면체 옆의 63.43° 틈을 채우려고 자른 조각(황금비 조각이 아님).",
  'wiz.3d.studies': "유클리드–케플러–파치올리 셀로 정확히 만든 입체를 하나씩: 창, 그 변형, 늘인 정십이면체. 복사본으로 또는 입체 자체로 밀어 보세요.",
  'shear.gap': "빨간 띠: 여기서는 셀이 공간을 채우지 않습니다(부피가 격자의 셀 부피와 다릅니다). 셀 0은 항상 채웁니다.",
