  'pv.bridges.section.slices': "단면",
  'pv.bridges.section.corners': "꼭짓점",
  'pv.detail.bridges': "3D+ 브리지",
  'pv.detail.zomeCredit': "DICTO가 Zometool로 발견. 중간 크기 파란 스트럿만으로 만든 형태로, 모든 모서리가 Zome의 파란 방향을 따릅니다.",
  'pv.detail.bainCredit': "베인 변형에서: 체심입방 격자를 한 축을 따라 √2배 늘리면 면심입방 격자가 됩니다. 이것은 그 변형에서 모든 모서리가 같은 셀로, DICTO가 Kaleidohedra에서 찾고 검증했습니다. 마름모 십이면체 형태는 이미 알려져 있었고, 정육각형 늘린 십이면체(깎은 팔면체에서 띠 하나를 없앤 모양)도 알려져 있었으며 DICTO는 이 새로운 경로로 독립적으로 도달했습니다. 다른 늘린 십이면체는 DICTO가 발견했습니다.",
  'pv.detail.regularNineCredit': "Kaleidohedra Regular 9 중 하나: 모든 모서리가 같고 면이 정사각형, 정육각형, 60° 마름모(정삼각형 두 개)뿐인, 공간을 채우는 도형은 이것들뿐입니다. DICTO를 위한 Kaleidohedra의 양방향 탐색으로 정확히 9가지를 찾았고, 이것은 여기에 새로 더해진 4가지 중 하나입니다.",
  'pv.detail.dictoSkewedEdCredit': "Kaleidohedra에서 DICTO의 기울어진 마름모 십이면체에 다섯 번째 모서리 방향을 더해 발견. Kaleidohedra 자체의 등변 늘린 십이면체 탐색과 일치합니다.",
  'pv.detail.dogstarCredit': "도그스타는 George W. Hart의 십이면체 별모양 8번(1996)으로, Hart는 정십이면체와 번갈아 놓으면 공간을 채운다고 적었습니다. Polyhedra-World에도 실려 있습니다. Hans Walser도 정육면체에서 모임지붕 6개를 떼어 낸 모양(그가 말하는 '준정십이면체')으로 설명하며, 정십이면체와 함께 3D 체스판처럼 공간을 채웁니다. DICTO가 도그스타라 이름 붙였고, 면에 도그스타 6개를 붙인 정십이면체를 선스타라 부릅니다.",
  'pv.detail.ekpLink': "DICTO의 Euclid–Kepler–Pacioli 셀의 일부입니다. 층 안에 층으로 쌓아 올린 모습은 다음에서 볼 수 있습니다:",
  'pv.bridge.CUBE': "tesseract {4,3,3}의 셀이자 단면. 24-cell {3,4,3}의 꼭짓점 도형.",
  'pv.bridge.CUBOCTAHEDRON': "24-cell {3,4,3}을 셀 쪽에서 본 그림자의 윤곽. 기울인 축으로 자른 적도 단면.",
  'pv.bridge.D20': "600-cell {3,3,5}의 꼭짓점 도형. snub 24-cell의 셀 중 하나.",
  'pv.bridge.D4': "5-cell {3,3,3}, 16-cell {3,3,4}, 600-cell {3,3,5}의 셀. tesseract {4,3,3}와 120-cell {5,3,3}의 꼭짓점 도형.",
  'pv.bridge.D8': "24-cell {3,4,3}의 셀. 16-cell {3,3,4}의 적도 단면이자 그 꼭짓점 도형.",
  'pv.bridge.DICTO_SKEWED_RD': "tesseract {4,3,3}의 비스듬한 그림자: 파란 스트럿으로 된 네 모서리 방향은 tesseract의 네 모서리 방향을 비스듬히 투영한 것입니다. 정규 RD는 정면에서 본 그림자입니다.",
  'pv.bridge.DODECAHEDRON': "120-cell {5,3,3}의 셀.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_OBLATE': "6차원 정육면체의 3D 면의 그림자: 3D 펜로즈 타일링(6D 정이십면체 준결정)의 타일.",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_PROLATE': "6차원 정육면체의 3D 면의 그림자: 3D 펜로즈 타일링(6D 정이십면체 준결정)의 타일.",
  'pv.bridge.J1_SQUARE_PYRAMID': "마름모 쌓기(tesseract + 정육면체 뿔 8개 = 24-cell {3,4,3})에서 정육면체 뿔의 셀. 두 개가 만나 24-cell의 정팔면체 하나가 된다. 3D에서는 정육면체에 여섯 개를 얹으면 RD가 된다.",
  'pv.bridge.PENROSE_PRISM_THICK': "두꺼운(72°) 펜로즈 마름모(5차원 정육면체의 정사각형 면의 그림자)를 모서리 하나 높이로 세운 것: 층을 이루는 5D 십각형 준결정의 타일.",
  'pv.bridge.PENROSE_PRISM_THIN': "얇은(36°) 펜로즈 마름모(5차원 정육면체의 정사각형 면의 그림자)를 모서리 하나 높이로 세운 것: 층을 이루는 5D 십각형 준결정의 타일.",
  'pv.bridge.PYRAMID_TRI_G2': "2등급 피라미드로서의 정사면체: 5-cell {3,3,3}, 16-cell {3,3,4}, 600-cell {3,3,5}의 셀.",
  'pv.bridge.RHOMBIC_DODECAHEDRON': "tesseract {4,3,3}와 24-cell {3,4,3}의 그림자(꼭짓점 쪽에서 본 투영).",
  'pv.bridge.RHOMBIC_ICOSAHEDRON': "5차원 정육면체의 그림자(투영): 다섯 축의 황금 조노헤드론.",
  'pv.bridge.RHOMBIC_TRIACONTAHEDRON': "6차원 정육면체의 그림자(투영): 여섯 축 모두의 황금 조노헤드론.",
  'pv.bridge.TRUNCATED_OCTAHEDRON': "4차 순열다면체(꼭짓점은 1, 2, 3, 4의 24가지 순서이며 4D 공간의 3D 단면에 있다). omnitruncated 5-cell의 셀 중 하나.",
