  'cat.zonohedra': '环带多面体',
  'cat.zonohedraDesc': '由铺砌自身的块组成的形状，在它们出现的任何地方都能找到。',
  'cat.polytopes': '多胞体',
  'cat.polytopesDesc': '顶点位于格点上的高维多胞体的影子，放在一个顶点处。它们叠在铺砌上而不阻挡块；截面中的顶点会亮起。',
