  'con.prompt.hexagon': "六边形：由三个方向的 {n} 个单元形成。现在笼目之星在它周围生长，每点按一次一条棱。",
  'con.prompt.junctionXY': "连接点：XY，即 X 与 Y 的合成；仍是二维。",
  'con.prompt.kagome': "笼目之星：由 {n} 个单元形成，三个方向的六条线。周围是笼目晶格。继续点按：Z 升起，成为烧绿石。",
  'con.prompt.tt': "截角四面体：三维中的笼目六边形，即躯干：四个六边形、四个三角形。接着是四肢：每个三角形上一个四面体，四个一次点按完成。",
  'con.prompt.pyrochlore': "烧绿石：{n} 个单元，截角四面体的每个三角形上各有一个四面体，合成一个大四面体，即 3D+ 的烧绿石零件。周围是烧绿石晶格。 继续点按：W 升起，成为超烧绿石。",
  'con.prompt.t5': "截角五胞体：四维中的躯干，五个截角四面体（你的是其中之一）和五个四面体。接着是四肢，五个一次点按完成。",
  'con.prompt.hyper': "超烧绿石：{n} 个单元，一个大五胞体，即截角五胞体的每个四面体上各有一个小五胞体。点按使它沿 W 旋转，再点按停止。",
  'con.prompt.startKagome': "点按填满橙色单元：六边形的第一条边，沿 X。",
