  'con.prompt.rhombus': "菱形：RD 自己的面，{n} 个单元，70.53° 与 109.47°。继续点按：Z 升起，进入 RD，先是躯干。",
  'con.prompt.rdBody': "立方体：RD 内部的躯干；它的棱是菱形的短对角线。接着是四肢：每个面上一个棱锥，六个一次点按完成。",
  'con.prompt.rd': "菱形十二面体：立方体加六个棱锥，十二个菱形，{n} 个单元。周围是它晶格中的十二个 RD。 继续点按：W 把它的角一分为二。",
  'con.prompt.rdTesseract': "超立方体：RD 的立方体，其角在 W 方向一分为二，即四维的躯干。接着是四肢：六个顶点一次点按连接两侧，再点按一次沿 W 加上另外两个。",
  'con.prompt.cell24': "24 胞体：96 条棱，RD 的四维对应物；它沿 W 的影子就是 RD。点按使它沿 W 旋转，再点按停止。",
  'con.prompt.cube': "立方体：由 {n} 个单元形成。现在第四个方向 W 从角上向内伸出：继续点按来搭建超立方体。",
  'con.prompt.tesseract': "超立方体：由 {n} 个单元形成。点按使它沿 W 旋转，再点按停止。",
  'con.prompt.square': "正方形：由 {n} 个单元形成。现在 Z 从角上升起：继续点按来搭建立方体。",
  'con.prompt.edges': "现在每点按一次，就填满一条剩下的棱。",
  'con.prompt.parts': "现在每点按一次添加一个完整部分；相同的部分一起出现。",
