  'theaetetus.note.theaetetus': "棱长 1 的二十面体分成 20 个 Cleo-Ico，外面的十二面体分成 20 根柱（二十面体每个面一根，其对偶伙伴），再由 Spheres of Dharma 的各层延伸到 DICTO 百二面体：102 块，没有一块有凹陷（DICTO）。Cleo 星视图让同一个核心向外生长：在其面上再立 20 个 Cleo-Ico 作为尖刺，尖端正是一个十二面体（玻璃）的顶点，并有 12 个五棱锥从其面向内插入。另有 30 个四面体填满沿棱的谷，共 82 块。",
