  'icosa.note.LOTUS_SEED': "棱长 φ² 的正二十面体，恰好切成 12 个正二十面体、一个小的和空隙部件 AXE、FUJI、CLEO。视图：113 个部件；DICTO 自己的拼法，正十二面体 + 12 个 J11 + 30 个 AXE + 20 个 FUJI；或中心周围的 12 个 Hasu 单元（#19）。",
  'icosa.note.UNITY': "DICTO 的 13 胞：二十·十二面体每个五边形上一个 J11；12 个 J11 只在它的 30 个顶点相接（#19）。",
  'icosa.note.VENUS': "UNITY 的 20 个凹窝由 VAJRA 封住（#19）。",
  'icosa.note.STELLA_CORONA': "一个二十·十二面体，三角形上 20 个正二十面体，五边形上 12 个 King of Pentacles：33 个部件闭合，每处接触都是整面。DICTO-Star 的正二十面体孪生（#20）。",
  'icosa.note.KEPLER_STAR_DIADEM': "每个五角星上放一个 Kepler Star 的 DICTO Stella-Corona。填补空隙会加入封住细缝的 120 个 Shark Tooth（60 对镜像）（#20）。",
  'icosa.note.DESHI': "正十二面体五边形上的 12 个正二十面体，围着一个小正二十面体，共享 30 条棱。这一排列出自 R. W. Gray（2002）（#19）。",
  'icosa.note.TWELVE_STAR_VOIDS': "二十·十二面体的 20 个三角形上各一个正二十面体。20 个正二十面体的壳是 Wolfram Demonstration“Cluster of 20 Icosahedra”（#20）。",
  'icosa.note.KEPLER_MACE': "两个 DICTO Stella-Corona 沿五次轴由一个 Kepler Star 相连：MACE 网络的键（#20）。",
  'icosa.note.AXE': "空隙部件：五条棱长 1，一条棱长 1/φ，体积 1/12。填补两个正二十面体在棱周围留下的空隙。Mosseri–Sadoc 拼块 t6 的 1/τ 倍（Mosseri & Sadoc 1982）。",
  'icosa.note.FUJI': "空隙部件：Lotus seed 每个外顶点处的六棱锥，体积 (1 + 3√5)/24。",
  'icosa.note.CLEO': "空隙部件：Lotus seed 每个内顶点处的细长四面体。Mosseri–Sadoc 拼块 t4 的 1/τ 倍（Mosseri & Sadoc 1982）。",
  'icosa.note.TRISKELION': "CLEO 与它的 3 个内侧 AXE 合为一个部件。",
  'icosa.note.TRISKELION_HEX': "FUJI 与它的 3 个 AXE 合为一个部件。",
  'icosa.note.INNER_EYE': "Lotus seed 外侧 12 个正二十面体围出的空间：去掉 12 个帽的正十二面体。",
  'icosa.note.HASU': "一个外侧正二十面体及其鳍片：12 个加上小中心构成 Lotus seed，每个都能直直取出。",
  'icosa.note.VAJRA': "封住 UNITY 一个凹窝的凸部件。",
  'icosa.note.HMV': "J2 帽加 5 个 AXE 和 5 个 CLEO：填满 Stella-Corona 五边形凹窝的部分。",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) 作为一个凸部件。",
  'icosa.note.KING_OF_PENTACLES': "HMV 加上外圈 AXE，顶面是平的五角星：Stella-Corona 每个五边形上一个。",
  'icosa.note.HOUND_TOOTH': "空隙部件：Mosseri–Sadoc 拼块 t2 的 1/τ 倍（Mosseri & Sadoc 1982），恰好嵌在五角星三角形与小二十·十二面体之间。",
  'icosa.note.TRICAP': "空隙部件：Mosseri–Sadoc 拼块 t3 的 1/τ 倍（Mosseri & Sadoc 1982），单位三角形上的扁锥。",
  'icosa.note.KEPLER_STAR': "开普勒的小星形十二面体（1619）的 1/φ 倍，去掉底部的尖：以整面坐在 King of Pentacles 的五角星上。",
  'icosa.note.SHARK_TOOTH': "为填补 Kepler Star Diadem 的 26.06° 细缝而切出的部件（非黄金比）：120 个，成镜像对。",
