  'studies.checker': "窗与星形八面体，棋盘排列",
  'studies.apart': "分开",
  'studies.note.checker': "星形八面体是窗的另一半：偶数晶胞放窗，奇数晶胞放星形八面体；每个奇数立方体恰好由它的星形八面体和六个相邻晶胞被挖过的屋顶组成，无空隙、无重叠。体积 12 + 4 = 两个立方体。把它们分开，看它们如何嵌合。",
  'studies.dogstar': "正十二面体与犬星",
  'studies.note.dogstar': "偶数晶胞中的正十二面体（其最密的格点堆积）在每个奇数晶胞留下一个空洞，这个空洞恰好是一个犬星（Dogstar）：缩小到 1/φ³ 的十二面体的部分星形化（核心、全部 12 个棱锥、30 个楔块中的 24 个，以及指向立方体顶角的 8 个尖角），位于该晶胞的星形八面体之内。它的棱长只有 2/φ⁴、2/φ³、2/φ² 和 2/φ。十二面体与犬星填满空间；把它们分开来看。 犬星就是 George W. Hart 的十二面体第 8 号星形（1996），他指出它与正十二面体交替排列可填满空间；Polyhedra-World 也收录了它。Hans Walser 也描述过它：把立方体的六个四坡屋顶切掉后剩下的形状（他称之为“半正十二面体”），它与正十二面体像三维棋盘一样填满空间。",
  'studies.stretch': "拉伸的十二面体",
  'studies.slider.stretch': "拉伸",
  'studies.shear.copies': "剪切：晶格上的副本",
  'studies.shear.solid': "剪切：立体本身",
  'studies.expanded': "凸化的窗（向外推出）",
  'studies.push': "推出",
  'studies.note.expanded': "每个菱形保持大小和角度径直向外推出，取凸包。在黄金推出量（0.727）时，立方体各面上方的空隙展平为 6 个黄金菱形：12 个粗菱形、6 个黄金菱形、8 个正三角形和 48 个三角形。",
  'studies.icosido': "从窗变为截半二十面体",
  'studies.morph': "变形",
  'studies.note.icosido': "每个菱形保持大小和 72° 形状，沿法线并在自身平面内滑动。最终它们的凸包是截半二十面体（12 个正五边形、20 个正三角形）：每个菱形位于一个五边形中，而五边形正是一个 72° 菱形加一个黄金三角形。",
  'studies.rdMorph': "从窗变为菱形十二面体",
  'studies.note.rdMorph': "每个窗保持其立方体棱（长对角线）不动，另一条对角线绕它旋转并伸长，经过正方形，直到 12 个正好闭合成菱形十二面体，其菱形以立方体棱为短对角线。",
  'studies.note.windows': "12 个 72° 和 108° 的菱形，各自位于十二面体本身的面平面上、立方体的一条棱上；挖去的部分由 48 个三角形围成。体积恰好为 12。",
  'studies.note.windowsStellas': "12 个 72° 和 108° 的菱形，各自位于十二面体本身的面平面上、立方体的一条棱上；挖去的部分由 48 个三角形围成。体积恰好为 12。",
  'studies.note.stretch': "任何拉伸量下都是 8 个正五边形、4 个六边形和 2 个矩形；拉伸一条棱长（1.236）时为正方形；拉伸 2 时为两个面相邻者的凸包。",
  'wiz.3d.targets': "160 个目标单元：所有棱长相等、棱只以特殊角度相交的空间填充单元。选一个，单独查看、与面相邻的单元一起查看，或作为其晶格的一个块查看。",
  'wiz.3d.ocdStella': "DICTO OCD Stella 位于 Ogdoecontahedron 堆积的一个网络上，另一个网络上是正二十面体、正八面体或更多 OCD Stella。",
