  'pv.detail.bridges': "3D+ 桥接",
  'pv.detail.zomeCredit': "由 DICTO 用 Zometool 发现，只用中号蓝色支杆搭成：每条棱都沿着 Zome 的一个蓝色方向。",
  'pv.detail.bainCredit': "来自贝恩拉伸：把体心立方晶格沿一个轴拉长 √2 倍，就变成面心立方晶格。这些是该拉伸下所有棱等长的胞体，由 DICTO 在 Kaleidohedra 中发现并验证。菱形十二面体的这种形式早已为人所知；正六边形伸长十二面体（去掉一个带的截角八面体）也已为人所知，DICTO 通过这条新途径独立得到它；另一个伸长十二面体由 DICTO 发现。",
  'pv.detail.regularNineCredit': "Kaleidohedra Regular 9 之一：所有棱等长、面只有正方形、正六边形或 60° 菱形（每个由两个正三角形组成）的空间填充形状只有这些。Kaleidohedra 为 DICTO 做的双向搜索恰好找到九种；这是在这里新增的四种之一。",
  'pv.detail.dictoSkewedEdCredit': "在 Kaleidohedra 中，通过给 DICTO 的歪斜菱形十二面体添加第五条棱方向而发现，与 Kaleidohedra 自己的等棱伸长十二面体搜索相匹配。",
  'pv.detail.dogstarCredit': "犬星就是 George W. Hart 的十二面体第 8 号星形（1996），他指出它与正十二面体交替排列可填满空间；Polyhedra-World 也收录了它。Hans Walser 也描述过它：把立方体的六个四坡屋顶切掉后剩下的形状（他称之为“半正十二面体”），它与正十二面体像三维棋盘一样填满空间。DICTO 将它命名为犬星（Dogstar），并把面上带有 6 个犬星的正十二面体称为太阳星（Sunstar）。",
  'pv.detail.ekpLink': "DICTO 的 Euclid–Kepler–Pacioli 单元的一部分，层层嵌套的构建过程见",
  'pv.bridge.CUBE': "tesseract {4,3,3} 的胞和截面；24-cell {3,4,3} 的顶点图。",
  'pv.bridge.CUBOCTAHEDRON': "24-cell {3,4,3} 从胞方向的影子的轮廓；沿倾斜轴的赤道截面。",
  'pv.bridge.D20': "600-cell {3,3,5} 的顶点图；snub 24-cell 的一种胞。",
  'pv.bridge.D4': "5-cell {3,3,3}、16-cell {3,3,4} 和 600-cell {3,3,5} 的胞；tesseract {4,3,3} 和 120-cell {5,3,3} 的顶点图。",
  'pv.bridge.D8': "24-cell {3,4,3} 的胞；16-cell {3,3,4} 的赤道截面，也是它的顶点图。",
  'pv.bridge.DICTO_SKEWED_RD': "tesseract {4,3,3} 的斜影：它的四个蓝色支杆棱方向，就是 tesseract 的四个棱方向斜着投影下来。正规 RD 是正对着的影子。",
  'pv.bridge.DODECAHEDRON': "120-cell {5,3,3} 的胞。",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_OBLATE': "6 维立方体一个 3D 面的影子：3D 彭罗斯镶嵌（6D 二十面体准晶）的一块。",
  'pv.bridge.GOLDEN_RHOMBOHEDRON_PROLATE': "6 维立方体一个 3D 面的影子：3D 彭罗斯镶嵌（6D 二十面体准晶）的一块。",
  'pv.bridge.J1_SQUARE_PYRAMID': "菱形堆叠（tesseract + 8 个立方锥 = 24-cell {3,4,3}）中立方锥的胞：两个合成 24-cell 的每个八面体。在三维中，立方体上放六个就成为 RD。",
  'pv.bridge.PENROSE_PRISM_THICK': "粗（72°）彭罗斯菱形（5 维立方体一个正方形面的影子）升高一条棱：分层的 5D 十边形准晶的一块。",
  'pv.bridge.PENROSE_PRISM_THIN': "细（36°）彭罗斯菱形（5 维立方体一个正方形面的影子）升高一条棱：分层的 5D 十边形准晶的一块。",
  'pv.bridge.PYRAMID_TRI_G2': "作为 2 级棱锥的正四面体：5-cell {3,3,3}、16-cell {3,3,4} 和 600-cell {3,3,5} 的胞。",
