  'ss.count': "Додекаэдров: {even}, звёзд-псов: {odd}",
  'ss.axes': "Оси пятого порядка",
  'ss.prompt.start': "Коснитесь светящейся детали, чтобы поставить её, затем касайтесь граней, чтобы добавлять детали за ними.",
  'ss.prompt.hole': "За этой гранью скрытая деталь; переключите вид, чтобы поставить её.",
  'ss.prompt.taken': "Эта ячейка уже занята.",
  'wiz.3d.stellaJewel': "Самоцветы DICTO и звёздчатые октаэдры заполняют пространство в шахматном порядке, или одни самоцветы, грань к грани по ромбам.",
  'wiz.3d.djTetra': "Четыре самоцвета DICTO тетраэдром, каждая пара грань к грани, ставятся целиком; со звёздчатыми октаэдрами заполняют пространство.",
  'wiz.3d.djOcta': "Шесть самоцветов DICTO вокруг звёздчатого октаэдра — сплошная фигура, горящая в центре; со звёздчатыми октаэдрами заполняют пространство.",
  'wiz.3d.djOctet': "Группы, делящие самоцветы, как ячейки октет-фермы, каждый звёздчатый октаэдр внутри октаэдрической группы: синее вечное пламя.",
  'wiz.3d.djKagome': "Тетраэдрические группы делят по одному самоцвету, как в кагоме; одиночные самоцветы между ними заполняются сами, фиолетовым.",
  'wiz.3d.djHexa': "DICTO Hexa — по восемь самоцветов DICTO в кубе — по алмазному узору: каждая делит четыре угловых самоцвета с соседями, а звёздчатые октаэдры заполняют все ячейки между ними.",
  'wiz.3d.ssTetra': "Четыре додекаэдра вокруг угла ячейки, ставятся целиком; с Dogstar заполняют пространство.",
  'wiz.3d.ssOcta': "Шесть додекаэдров вокруг Dogstar — Sunstar наизнанку, горящая в центре; с Dogstar заполняют пространство.",
  'wiz.3d.ssOctet': "Группы додекаэдров как ячейки октет-фермы, каждый Dogstar внутри октаэдрической группы: синее вечное пламя.",
  'wiz.3d.ssKagome': "Группы додекаэдров вверх и вниз, делящие по одному додекаэдру, в стиле кагоме; фиолетовое пламя в каждой одиночной ячейке.",
