  'wiz.4d.z4': 'Тессеракт, 4D-куб, в каждой точке с целыми координатами. Его срез при w = 0 — единичный куб мира RD.',
  'wiz.4d.d4': '24-ячейник, 4D-аналог RD: его срез при w = 0 — мир FCC. Кнопка внизу переключает на установку 16-ячейников.',
  'wiz.4d.a4': '5-ячейники с общими вершинами на решётке A4; её срез Pyrochlore — это в точности мир Pyrochlore. Ставьте усечённые 5-ячейники, и их 5-ячейники появятся сами. Кнопка внизу переключает на битусечённые или одиночные 5-ячейники.',
