  'wiz.1d.constructKagome': "Постройте шестиугольник из 1D-клеток, затем вокруг него звезду кагоме (шесть линий в трёх направлениях), затем её решётку.",
  'wiz.1d.constructRd': "Постройте собственный ромб RD из 1D-клеток, затем ромбододекаэдр: сначала куб внутри, затем шесть пирамид; затем его решётку.",
  'con.open': "Открыть в {dim}",
  'wiz.2d.nets': "Пройдите призрачную развёртку тела грань за гранью, а затем сложите её в тело.",
  'nets.prompt.start': "Следуйте призрачной развёртке: нажмите, чтобы построить первую грань, сторона за стороной.",
  'nets.prompt.faces': "Теперь каждое касание строит следующую грань развёртки.",
  'nets.prompt.done': "{name}: развёртка готова. Нажмите, чтобы сложить, или тяните ползунок.",
  'nets.prompt.folded': "{name}: сложен из своей развёртки. Тяните ползунок, чтобы развернуть.",
  'nets.fold': "Сгиб: от плоского до закрытого",
  'pack.spheres': "Spherical: каждая деталь в виде шара; целые RD касаются двенадцати соседей. Ползунок меняет размер. Только вид; ваши клетки не меняются.",
  'pack.spheres@polyhedraverse': "Spherical: каждая форма в виде шара того же объёма, внутри формы. Ползунок меняет размер. Это только вид, формы не меняются.",
  'pack.voids': "Пустоты: промежутки между шарами, октаэдрические (золото, шесть шаров вокруг) и тетраэдрические (розовые, четыре вокруг), показаны только там, где полностью окружены.",
  'pack.off': "Spherical: выкл.",
  'pack.radius': "Размер шаров",
  'pack.none': "Поставьте несколько целых RD, чтобы увидеть пустоты между ними.",
