  'gbp.note.double': "Вторая сеть в пустотах даёт одну объёмноцентрированную кубическую упаковку, 77,43 % пространства ({n} копий); 72 части на копию точно заполняют остальное.",
  'gbp.holes.on': "Зазор: Bull-horns OG adaptor",
