  'gbp.note.holes': "Смола вокруг двойной сети, разрезанная по пустотам между 6 OG: одна деталь, Bull-horns OG adaptor DICTO, 3 на копию. OG 77,4332 %, адаптеры 22,5668 % пространства — точно, без остатка ({n} копий).",
  'gbp.note.voice': "Голос {v} из 5: упаковка одного вписанного куба ({n} копий).",
