  'gbp.prompt.start': "Огдоэконтаэдр DICTO, соединённый грань к грани по шестиугольникам. Выберите вид внизу; «Строить» позволяет добавлять копии.",
  'dv.loading': "Загрузка деталей из статьи…",
  'dv.note.cycles': "Два цикла в одном пространстве: Сферы Дхармы (ваш цикл) и их полярное обращение (обращённый), каждое тело — прозрачная оболочка. В этой настройке они делят {shared} (золото). Сдвигайте ползунок от одного цикла к другому; посередине видны оба.",
  'dv.note.interlock': "Оба цикла как одно тело: каждый слой вашего цикла разрезан каждым слоем обращённого, {n} точных выпуклых деталей {k} видов на виток ({setName}), сектор вырезан, в центре следующий виток. Ползунок перекрашивает от ваших слоёв к обращённым. Коснитесь детали, чтобы узнать её имя.",
