  'dv.prompt.start': "Dual Vision: два цикла статьи в одном пространстве. Концы / середина сдвигает сферу обращения; коснитесь детали, чтобы узнать её имя.",
  'vj.loading': "Загрузка двенадцати станций…",
  'vj.note': "Золотой цикл из двенадцати станций, I ⊂ Cleo star ⊂ D′ ⊂ ID ⊂ O ⊂ rTI ⊂ TI ⊂ H ⊂ jtI ⊂ RT ⊂ M ⊂ I·φ³, в разрезе; внутренний виток виден в центре. Коснитесь оболочки, чтобы узнать её имя.",
  'vj.note.pieces': "Два последних шага заполнены: RT → M — 30 деталей одного вида, M → I·φ³ — 60 одного вида. Коснитесь детали, чтобы узнать её слой.",
