  'vj.view.oh': "DICTO Hecatogdoecontahedron",
  'vj.note.oh': "DICTO Hecatogdoecontahedron (статья #34a): DICTO Hecatodihedron H (золото) и его полярный DICTO Ogdoecontahedron O (бирюза) сцеплены в средней сфере усечённого икосаэдра; 182 грани и 182 вершины, самодвойственный. Ядро и оболочка показывают классические rectified и joined truncated icosahedron; ползунок разводит H и O. Нажмите на тело, чтобы назвать его.",
  'vj.core.on': "Ядро (rTI): вкл",
