  'vj.film.position': "Внутри одного витка",
  'vj.prompt.start': "Vajrayana: двенадцать станций золотого цикла. ▶ снимает их по одной, без конца; ⛶ превращает разрез в стекло.",
  'vj.prompt.film': "Фильм: ▶ снимает внешнюю станцию и приближается к следующей, останавливаясь на каждой; после витка цикл начинается снова, в φ³ раз меньше. ◀ собирает обратно наружу.",
  'vj.prompt.rtM': "RT → M: одна из 30 одинаковых деталей, по одной на каждой грани ромботриаконтаэдра.",
  'vj.prompt.mI': "M → I·φ³: одна из 60 одинаковых деталей, по одной на каждой грани DICTO Metaxyhexecontahedron.",
  'vj.prompt.core': "икосаэдр в центре, где кончается внутренний виток",
  'vj.prompt.cleoLink': "её сборка из 82 деталей — в Theaetetus (Сборка Cleo star ↗)",
  'wiz.3d.vajrayana': "Золотой цикл из двенадцати станций: додекаэдр возвращается как оболочка Cleo star, DICTO Metaxyhexecontahedron закрывает последний шаг; снимается станция за станцией.",
  'dv.xray.wedge': "Вырез: срез из статьи убран. Нажмите ⛶ ещё раз — появится плоскость, которую можно тянуть.",
  'dv.plane': "Плоскость",
  'dv.prompt.twin': "Золотой близнец выворачивает вложение: φ³ становится −1/φ³, и внутренний виток выходит больше внешнего. Здесь по одной станции.",
  'dv.prompt.twinTap': "Золотой близнец {name} (√5 → −√5, грани сохранены).",
  'dv.prompt.toggle.ends': "Общие концы (ρ² = φ²/4): циклы делят икосаэдр и додекаэдр; 536 деталей на виток.",
  'dv.prompt.toggle.middle': "Общая середина (ρ² = 3φ²/4): циклы делят икосододекаэдр и триаконтаэдр; 502 детали на виток.",
  'dv.film.unwrap': "Развернуть",
  'dv.film.wrap': "Свернуть",
  'dv.film.position': "Внутри одного витка",
  'dv.film.pause': "Пауза",
  'dv.film.twinPos': "Ваш → близнец",
  'dv.prompt.film': "Фильм: «Развернуть» снимает тело слой за слоем и уходит в следующий виток без конца; «Свернуть» ведёт обратно наружу. На каждой станции пауза; нажмите текущее направление ещё раз, чтобы остановить.",
  'dv.short.cycles': "Два цикла в одном пространстве; общие: {shared}. Ползунок — от вашего к обращённому.",
  'dv.short.interlock': "{n} точных деталей {k} видов на виток ({setName}). Коснитесь детали, чтобы узнать имя.",
  'dv.short.layer': "Только слой {layer}: {ln} деталей в этой настройке.",
  'dv.short.twin': "Золотой близнец {name}: каждая вершина a + b√5 становится a − b√5, грани сохраняются (каждый кадр одного размера). ▶ проходит через рациональную тень (√5 → 0) к близнецу, ◀ возвращает. Близнец стоит рядом.",
  'gbp.prompt.build': "Коснитесь шестиугольника, чтобы добавить копию, соединённую там, или коснитесь вспомогательного контура; долгое нажатие убирает копию.",
  'gbp.prompt.buildOff': "Включите «Строить», чтобы добавлять копии.",
