  'theaetetus.note.theaetetus': "Икосаэдр с ребром 1 как его 20 Cleo-Icos, додекаэдр вокруг как 20 колонн (по одной на грань икосаэдра, его дуального партнёра), затем слои Spheres of Dharma до гекатодиэдра DICTO: 102 детали, ни одной с выемкой (DICTO). Вид «Звезда Cleo» выращивает то же ядро наружу: ещё 20 Cleo-Icos встают на его гранях шипами, их вершины — вершины додекаэдра (стекло), и 12 пятиугольных пирамид входят внутрь с его граней, и 30 тетраэдров заполняют долины вдоль его рёбер: всего 82 детали.",
