  'chains.bodhi.hollow': "Полость: 60 Vajra",
  'chains.note.karma': "Икосаэдр и додекаэдр как бесконечные оболочки друг друга (DICTO #22).",
  'chains.note.dharma': "Шесть икосаэдрических оболочек, каждая заполнена точно, повтор каждые φ³ (DICTO #23).",
  'chains.note.bodhi': "Двенадцать триаконтаэдров и ещё один внутри триаконтаэдра в φ² раз больше, зазор заполнен точно (DICTO #24).",
  'icosa.fill.off': "Заполнить зазоры: выкл.",
  'icosa.fill.on': "Заполнить зазоры: вкл. (120 Shark Teeth)",
  'icosa.note.LOTUS_SEED': "Правильный икосаэдр с ребром φ², разрезанный точно на 12 икосаэдров, один маленький и детали зазоров AXE, FUJI и CLEO. Виды: 113 деталей; собственная сборка DICTO, додекаэдр + 12 J11 + 30 AXE + 20 FUJI; или 12 модулей Hasu вокруг центра (#19).",
  'icosa.note.UNITY': "13-ячейка DICTO: икосододекаэдр с J11 на каждом пятиугольнике; 12 J11 касаются только в его 30 вершинах (#19).",
  'icosa.note.VENUS': "UNITY с 20 впадинами, закрытыми VAJRA (#19).",
  'icosa.note.STELLA_CORONA': "Икосододекаэдр, 20 икосаэдров на его треугольниках и 12 King of Pentacles на пятиугольниках: 33 детали, замкнуто, каждое касание — целая грань. Икосаэдрический двойник DICTO-Star (#20).",
  'icosa.note.KEPLER_STAR_DIADEM': "DICTO Stella-Corona с Kepler Star на каждой пентаграмме. «Заполнить зазоры» добавляет 120 Shark Teeth (60 зеркальных пар), закрывающих узкие щели (#20).",
  'icosa.note.DESHI': "12 икосаэдров на пятиугольниках додекаэдра вокруг маленького икосаэдра, с 30 общими рёбрами. Расположение принадлежит R. W. Gray (2002) (#19).",
  'icosa.note.TWELVE_STAR_VOIDS': "Икосододекаэдр с икосаэдром на каждом из 20 треугольников. Оболочка из 20 икосаэдров — Wolfram Demonstration «Cluster of 20 Icosahedra» (#20).",
  'icosa.note.KEPLER_MACE': "Две DICTO Stella-Corona, соединённые одной Kepler Star вдоль оси пятого порядка: связь сети MACE (#20).",
  'icosa.note.AXE': "Деталь зазора: пять рёбер 1, одно ребро 1/φ, объём 1/12. Заполняет зазор, который два икосаэдра оставляют вокруг ребра. Плитка t6 Моссери–Садока в масштабе 1/τ (Mosseri & Sadoc 1982).",
  'icosa.note.FUJI': "Деталь зазора: шестиугольная пирамида у каждой внешней вершины Lotus seed, объём (1 + 3√5)/24.",
  'icosa.note.CLEO': "Деталь зазора: тонкий тетраэдр у каждой внутренней вершины Lotus seed. Плитка t4 Моссери–Садока в масштабе 1/τ (Mosseri & Sadoc 1982).",
  'icosa.note.TRISKELION': "CLEO с тремя внутренними AXE, одной деталью.",
  'icosa.note.TRISKELION_HEX': "FUJI с тремя AXE, одной деталью.",
  'icosa.note.INNER_EYE': "Пространство, которое охватывают 12 внешних икосаэдров Lotus seed: додекаэдр без 12 шапочек.",
  'icosa.note.HASU': "Один внешний икосаэдр с плавниками: 12 таких и маленький центр образуют Lotus seed, и каждый вынимается прямо.",
  'icosa.note.VAJRA': "Выпуклая деталь, закрывающая одну впадину UNITY.",
  'icosa.note.HMV': "Шапочка J2 с 5 AXE и 5 CLEO: то, что заполняет пятиугольную впадину Stella-Corona.",
  'icosa.note.FIVE_OF_CUPS': "HMV (Gramophone) одной выпуклой деталью.",
  'icosa.note.KING_OF_PENTACLES': "HMV с внешним кольцом AXE и плоской пентаграммой сверху: по одной на каждом пятиугольнике Stella-Corona.",
  'icosa.note.HOUND_TOOTH': "Деталь зазора: плитка t2 Моссери–Садока в масштабе 1/τ (Mosseri & Sadoc 1982), точно входит между треугольником пентаграммы и маленьким икосододекаэдром.",
  'icosa.note.TRICAP': "Деталь зазора: плитка t3 Моссери–Садока в масштабе 1/τ (Mosseri & Sadoc 1982), плоская пирамида на единичном треугольнике.",
  'icosa.note.KEPLER_STAR': "Малый звёздчатый додекаэдр Кеплера (1619) в масштабе 1/φ без шипа на основании: ложится на пентаграмму King of Pentacles целыми гранями.",
  'icosa.note.SHARK_TOOTH': "Деталь, вырезанная для щелей 26,06° в Kepler Star Diadem (не золотая): 120 штук, зеркальными парами.",
  'icosa.note.BERMUDA_PYRAMID': "Деталь, вырезанная для зазора 63,43° рядом с маленьким додекаэдром (не золотая).",
  'wiz.3d.studies': "По одному телу, точно построенному из ячейки Евклида–Кеплера–Пачоли: окна, их превращения и вытянутый додекаэдр. Сдвигайте их копиями или как само тело.",
  'shear.gap': "Красная полоса: здесь ячейка уже не заполняет пространство (её объём не равен объёму ячейки решётки). При Ячейке 0 — всегда заполняет.",
