  'kept.check.unavailable': "эта версия не может построить его заново",
  'studies.study': "Этюд",
  'studies.windows': "Окна: додекаэдр минус шесть звёздчатых октаэдров",
  'studies.windowsStellas': "Окна и шесть звёздчатых октаэдров",
  'studies.checker': "Окна и звёздчатые октаэдры, в шахматном порядке",
  'studies.apart': "Раздвинуть",
  'studies.note.checker': "Звёздчатый октаэдр — вторая половина окон: окна в чётных ячейках, звёздчатые октаэдры в нечётных, и каждый нечётный куб — это его звёздчатый октаэдр плюс вырезанные крыши шести соседей, без зазоров и наложений. Объёмы 12 + 4 = два куба. Раздвиньте, чтобы увидеть, как они сходятся.",
  'studies.dogstar': "Додекаэдры и их звёзды-псы",
  'studies.note.dogstar': "Правильные додекаэдры в чётных ячейках (их самая плотная решётчатая упаковка) оставляют по одной пустоте в каждой нечётной ячейке, и эта пустота — в точности звезда-пёс (Dogstar): частичная звёздчатая форма додекаэдра в 1/φ³ их размера (ядро, все 12 пирамид, 24 из 30 клиньев и 8 лучей к углам куба) внутри звёздчатого октаэдра ячейки. Её рёбра только 2/φ⁴, 2/φ³, 2/φ² и 2/φ. Додекаэдры и звёзды-псы заполняют пространство; раздвиньте, чтобы увидеть. Звезда-пёс — это звёздчатая форма додекаэдра № 8 Джорджа Харта (1996); Харт отметил, что она заполняет пространство, чередуясь с правильными додекаэдрами. Она есть и на Polyhedra-World. Ханс Вальзер (Hans Walser) тоже описывает её — как куб со срезанными шестью вальмовыми крышами (его «полуправильный додекаэдр»), который вместе с правильными додекаэдрами заполняет пространство, как трёхмерная шахматная доска.",
  'studies.stretch': "Растянутый додекаэдр",
  'studies.slider.stretch': "Растяжение",
  'studies.shear.copies': "Сдвиг: копии на решётке",
  'studies.shear.solid': "Сдвиг: само тело",
  'studies.expanded': "Окна, ставшие выпуклыми (выдвинутые наружу)",
  'studies.push': "Выдвиг",
  'studies.note.expanded': "Каждый ромб выдвинут прямо наружу без изменения размера и углов; берётся выпуклая оболочка. При золотом выдвиге (0,727) щели над гранями куба становятся 6 золотыми ромбами: 12 толстых ромбов, 6 золотых ромбов, 8 правильных треугольников и 48 треугольников.",
  'studies.icosido': "Из окон в икосододекаэдр",
  'studies.morph': "Превращение",
  'studies.note.icosido': "Каждый ромб сдвигается вдоль нормали и в своей плоскости, сохраняя размер и угол 72°. В конце их выпуклая оболочка — икосододекаэдр (12 правильных пятиугольников, 20 правильных треугольников): каждый ромб лежит в пятиугольнике, а пятиугольник — это ромб с углом 72° плюс золотой треугольник.",
  'studies.rdMorph': "Из окон в ромбододекаэдр",
  'studies.note.rdMorph': "Каждое окно сохраняет ребро куба (свою длинную диагональ) и поворачивает и растягивает вокруг него другую диагональ, проходя через квадраты, пока 12 ромбов точно не сомкнутся в ромбододекаэдр, у ромбов которого ребро куба — короткая диагональ.",
  'studies.note.windows': "12 ромбов с углами 72° и 108°, каждый в плоскости грани самого додекаэдра, на ребре куба; вырезанная часть — 48 треугольников. Объём ровно 12.",
  'studies.note.windowsStellas': "12 ромбов с углами 72° и 108°, каждый в плоскости грани самого додекаэдра, на ребре куба; вырезанная часть — 48 треугольников. Объём ровно 12.",
  'studies.note.stretch': "При любом растяжении 8 правильных пятиугольников, 4 шестиугольника и 2 прямоугольника; квадраты при растяжении на одно ребро (1,236); при 2 — оболочка двух соседей по грани.",
  'wiz.3d.targets': "160 целевых ячеек: каждая заполняющая пространство ячейка с равными рёбрами, рёбра которой сходятся только под особыми углами. Выберите одну, чтобы увидеть её отдельно, с соседями по граням или блоком её решётки.",
  'wiz.3d.ocdStella': "DICTO OCD Stella на одной сети упаковки Ogdoecontahedron, а на другой — икосаэдры, октаэдры или другие OCD Stella.",
  'wiz.3d.doubleVision': "Spheres of Dharma и их полярное обращение в одном пространстве: два цикла, их сцепление и по одному слою.",
  'wiz.3d.cycles': "Пути от одного икосаэдра к его родственникам; каждый шаг показывает, что сохраняется.",
  'wiz.3d.theaetetus': "Ядро Cleo, выращенное до DICTO Hecatodihedron слой за слоем.",
  'wiz.3d.chains': "Три опубликованные вложенности DICTO: Chain of Karma, Spheres of Dharma и Bodhi Seed.",
  'wiz.3d.octet': "Крыши Евклида на икосаэдре: пять октетных сетей, растущих с ползунком.",
  'wiz.3d.thirteens': "Двенадцать вокруг одного, тринадцатью способами. Каждый центр золотой.",
  'wiz.3d.dodeca': "DICTO Dodeca-13, DICTO-Star и звезда DICTO-ICOSA в сборе.",
  'wiz.3d.octetBuild': "DICTO Icosahedral Octet для самостоятельной сборки: по ячейке или кластерами.",
  'wiz.3d.breathing': "Большие и малые тетраэдры вершина к вершине; ползунок от золотого сечения до правильного пирохлора.",
  'wiz.3d.bodhiPyro': "DICTO Ogdoecontahedron, соединённый по шестиугольникам в пирохлорные сети.",
